                    if (sel.value) {
                        var so = sel.options[sel.selectedIndex];
                        inp.value = (so && so.text) ? so.text : sel.value;
                    } else {
                        inp.value = '';
                    }
                    if (typeof window.clearInvalidFieldMarker === 'function') {
                        window.clearInvalidFieldMarker(selectId);
                    }
                    inp.dispatchEvent(new Event('change', { bubbles: true }));
                    // Do NOT dispatch change on #buyingDate here: the select has onchange="syncComboboxInput('buyingDate')"
                    // and would re-enter this function until the stack overflows. FAB / native select already fire
                    // change on the select when the user picks a value (see rebuildRixoBuyingDateFabFromSelect).
                    if (typeof window.updateRixoBuyingDateFabTriggerLabel === 'function') {
                        window.updateRixoBuyingDateFabTriggerLabel();
                    }
                }
                return;
            }
            // Rixo Request generator: show option label in input (e.g. "Undefined"), value stays on select
            if (selectId === 'rixoCompany') {
                var sel = document.getElementById('rixoCompany');
                var inp = document.getElementById('rixoCompanyInput');
                if (sel && inp) {
                    if (sel.value) {
                        var so = sel.options[sel.selectedIndex];
                        inp.value = (so && so.text) ? so.text : sel.value;
                    } else {
                        inp.value = '';
                    }
                    if (typeof window.clearInvalidFieldMarker === 'function') {
                        window.clearInvalidFieldMarker(selectId);
                    }
                    inp.dispatchEvent(new Event('change', { bubbles: true }));
                    if (typeof window.updateRixoCompanyFabTriggerLabel === 'function') {
                        window.updateRixoCompanyFabTriggerLabel();
                    }
                }
                return;
            }
            // Prevent infinite recursion for chassis fields
            if (window.__syncingChassis === true && (selectId === 'chassis' || selectId === 'editChassis')) {
                return;
            }
            
            var select = document.getElementById(selectId);
            var inputId = selectId + 'Input';
            if (selectId === 'rixoPriceDropdown') {
                inputId = 'rixoPriceInput';
            } else if (selectId === 'editRixoPriceDropdown') {
                inputId = 'editRixoPriceInput';
            }
            var input = document.getElementById(inputId);
            if (select && input && select.value) {
                input.value = select.value;
                // Clear invalid field marker when valid value is selected
                if (typeof window.clearInvalidFieldMarker === 'function') {
                    window.clearInvalidFieldMarker(selectId);
                }
                // Trigger change event on input for any listeners
                input.dispatchEvent(new Event('change', { bubbles: true }));
                
                // For chassis field, DO NOT dispatch change event on select here
                // The change event is already dispatched by the option click handler
                // Dispatching it here causes infinite recursion
            }
            if (selectId === 'clientName' || selectId === 'editClientName') {
                if (typeof window.applyPurchaseCountryFromClientName === 'function') {
                    window.applyPurchaseCountryFromClientName(selectId);
                }
            }
        };
        
        // Multi-select combobox: append selected value with semicolon separator (for Grade field)
        window.appendMultiSelectValue = function(selectId) {
            var select = document.getElementById(selectId);
            var inputId = selectId + 'Input';
            var input = document.getElementById(inputId);
            if (select && input && select.value) {
                var currentValue = input.value.trim();
                var newValue = select.value.trim();
                
                if (currentValue === '') {
                    input.value = newValue;
                } else {
                    // Check if value already exists (avoid duplicates)
                    var existingValues = currentValue.split(';').map(function(v) { return v.trim(); });
                    if (existingValues.indexOf(newValue) === -1) {
                        input.value = currentValue + '; ' + newValue;
                    }
                }
                
                // Clear the select value to allow re-selection
                select.value = '';
                
                // Trigger change event on input for any listeners
                input.dispatchEvent(new Event('change', { bubbles: true }));
            }
        };
        
        // Function to open multi-select combobox dropdown (similar to regular combobox but appends values)
        window.openMultiSelectComboboxDropdown = function(selectId) {
            // Ensure base options for Fuel/Shift before opening (Grade options come from master_menu)
            if (typeof window.ensureBaseComboboxOptionsForAddEdit === 'function') {
                window.ensureBaseComboboxOptionsForAddEdit();
            }
            
            // ALWAYS close all other dropdowns first to prevent conflicts
            var allDropdowns = document.querySelectorAll('[id$="_dropdown"]');
            allDropdowns.forEach(function(dropdown) {
                var otherSelectId = dropdown.id.replace('_dropdown', '');
                if (otherSelectId !== selectId) {
                    dropdown.remove();
                }
            });
            
            // Prevent recursion: if dropdown already exists for this selectId, just update it
            var existingDropdown = document.getElementById(selectId + '_dropdown');
            if (existingDropdown) {
                var inputId = selectId + 'Input';
                var input = document.getElementById(inputId);
                var select = document.getElementById(selectId);
