        // Function to mark a field as invalid (red border and asterisk)
        window.markFieldAsInvalid = function(fieldId) {
            var inputId = fieldId + 'Input';
            if (fieldId === 'rixoPriceDropdown') {
                inputId = 'rixoPriceInput';
            } else if (fieldId === 'editRixoPriceDropdown') {
                inputId = 'editRixoPriceInput';
            }
            
            var input = document.getElementById(inputId);
            var label = null;
            if (input) {
                // Try multiple methods to find the label
                // Method 1: label with for attribute
                label = document.querySelector('label[for="' + inputId + '"]');
                // Method 2: label in parent div
                if (!label && input.parentElement) {
                    label = input.parentElement.querySelector('label');
                }
                // Method 3: label in grandparent div (for combobox structure)
                if (!label && input.parentElement && input.parentElement.parentElement) {
                    label = input.parentElement.parentElement.querySelector('label');
                }
                // Method 4: previous sibling label
                if (!label) {
                    var prevSibling = input.previousElementSibling;
                    while (prevSibling && !label) {
                        if (prevSibling.tagName === 'LABEL') {
                            label = prevSibling;
                        }
                        prevSibling = prevSibling.previousElementSibling;
                    }
                }
            }
            
            if (input) {
                // Add red border
                input.style.border = '2px solid #dc2626';
                input.style.borderRadius = '4px';
                
                // Clear the invalid value
                input.value = '';
                
                // Also clear the select value
                var select = document.getElementById(fieldId);
                if (select) {
                    select.value = '';
                }
                
                // Open dropdown to show options
                setTimeout(function() {
                    if (typeof window.openComboboxDropdown === 'function') {
                        window.openComboboxDropdown(fieldId);
                    }
                }, 100);
            }
            
            // Add red asterisk to label
            if (label) {
                // Remove existing asterisk if any
                var existingAsterisk = label.querySelector('.invalid-asterisk');
                if (existingAsterisk) {
                    existingAsterisk.remove();
                }
                
                // Add red asterisk
                var asterisk = document.createElement('span');
                asterisk.className = 'invalid-asterisk';
                asterisk.textContent = ' *';
                asterisk.style.color = '#dc2626';
                asterisk.style.fontWeight = 'bold';
                label.appendChild(asterisk);
            }
        };
        
