        // Function to validate if a combobox value exists in the dropdown options
        window.validateComboboxValue = function(fieldId, value) {
            // If value is empty, it's valid (empty is allowed)
            if (!value || value.trim() === '') {
                return { valid: true, message: '' };
            }
            
            // Special handling for chassis fields (two-part chassis: Part1-Part2)
            // Only validate Part 1 against dropdown options
            if (fieldId === 'chassis' || fieldId === 'editChassis') {
                // Extract Part 1 (everything before "-" or full value if no "-")
                var part1 = value.indexOf('-') !== -1 ? value.substring(0, value.indexOf('-')) : value;
                
                // Map field IDs to actual select element IDs
                var selectId = fieldId;
                
                var select = document.getElementById(selectId);
                if (!select) {
                    return { valid: false, message: 'Field not found: ' + fieldId };
                }
                
                // Check if Part 1 exists in select options
                var valueExists = false;
                for (var i = 0; i < select.options.length; i++) {
                    var option = select.options[i];
                    // Compare Part 1 with option value (case-insensitive)
                    if (option.value === part1 || 
                        option.value.toLowerCase() === part1.toLowerCase() ||
                        option.text === part1 ||
                        option.text.toLowerCase() === part1.toLowerCase()) {
                        valueExists = true;
                        break;
                    }
                }
            } else {
                // For non-chassis fields, validate the full value as before
                // Map field IDs to actual select element IDs
                var selectId = fieldId;
                
                // Handle special cases for Brand and Supplier Name (auctionName)
                if (fieldId === 'brand' || fieldId === 'editBrand') {
                    selectId = fieldId;
                } else if (fieldId === 'auctionName') {
                    selectId = 'auctionName';
                } else if (fieldId === 'editAuctionName') {
                    selectId = 'editAuctionName';
                }
                
                var select = document.getElementById(selectId);
                if (!select) {
                    return { valid: false, message: 'Field not found: ' + fieldId };
                }
                
                // Check if value exists in select options (compare both value and text)
                var valueExists = false;
                for (var i = 0; i < select.options.length; i++) {
                    var option = select.options[i];
                    // Compare both value and text (case-insensitive for text)
                    if (option.value === value || 
                        option.value.toLowerCase() === value.toLowerCase() ||
                        option.text === value ||
                        option.text.toLowerCase() === value.toLowerCase()) {
                        valueExists = true;
                        break;
                    }
                }
            }
            
            if (!valueExists) {
                // Create a readable field label
                var fieldLabel = fieldId
                    .replace(/^edit/, '')
                    .replace(/([A-Z])/g, ' $1')
                    .replace(/^./, function(str) { return str.toUpperCase(); })
                    .trim();
                
                // Special labels for common fields
                if (fieldId === 'auctionName' || fieldId === 'editAuctionName') {
                    fieldLabel = 'Supplier Name';
                } else if (fieldId === 'typeOfVehicle' || fieldId === 'editTypeOfVehicle') {
                    fieldLabel = 'Vehicle type';
                } else if (fieldId === 'chassis' || fieldId === 'editChassis') {
                    fieldLabel = 'Chassis';
                    // For chassis, mention Part 1 specifically
                    var part1 = value.indexOf('-') !== -1 ? value.substring(0, value.indexOf('-')) : value;
                    return { 
                        valid: false, 
                        message: 'Chassis Part 1 "' + part1 + '" is not in the dropdown list. Please select Part 1 from the dropdown.' 
                    };
                }
                
                return { 
                    valid: false, 
                    message: fieldLabel + ' value "' + value + '" is not in the dropdown list. Please select a value from the dropdown.' 
                };
            }
            
            return { valid: true, message: '' };
        };
        
        // Function to filter and update dropdown options based on search text
        window.filterComboboxDropdown = function(selectId, searchText) {
            var select = document.getElementById(selectId);
            if (!select) return;
            
            var inputId = selectId + 'Input';
            if (selectId === 'rixoPriceDropdown') {
                inputId = 'rixoPriceInput';
            } else if (selectId === 'editRixoPriceDropdown') {
                inputId = 'editRixoPriceInput';
            }
            
            var input = document.getElementById(inputId);
            if (!input) return;
            
            var dropdown = document.getElementById(selectId + '_dropdown');
            if (!dropdown) {
                // If dropdown doesn't exist, return early (don't call openComboboxDropdown to avoid infinite recursion)
                // The dropdown should be created by openComboboxDropdown before filterComboboxDropdown is called
                return;
            }
            
            // Get all options from the select
            if (!select.options || typeof select.options[Symbol.iterator] !== 'function') {
                return;
            }
            
            var allOptions = Array.from(select.options).slice(1).filter(function(opt) {
                var v = (opt.value || '').trim();
                return v !== '__SEE_MORE__' && v !== '__SEE_LESS__';
            }).map(function(opt) {
                return { value: opt.value, text: opt.text, disabled: opt.disabled };
            });
            
            // Car Brand Map modal only: inject standard fuel/shift lists when filtering.
            var baseOptionsMap = {
                carBrandFuel: ["GASOLINE", "DIESEL", "HYBRID", "CNG", "EV", "HYDROGEN", "PHEV"],
                carBrandShift: ["AT", "MT", "6F", "5F"]
            };
            if (baseOptionsMap[selectId]) {
                var existingValuesSet = new Set(allOptions.map(function(o) { return o.value; }));
                baseOptionsMap[selectId].forEach(function(opt) {
                    if (!existingValuesSet.has(opt)) {
                        allOptions.push({ value: opt, text: opt });
                    }
                });
            }
            
            // Filter options based on search text (case-insensitive)
            var searchLower = (searchText || '').toLowerCase().trim();
            
            var isRixoInlineTreeCombo = /^rixo-inline-path-/.test(selectId) || /^rixoLeafInline_/.test(selectId);
            // Rixo tree inline: while user types in the input, that text is the filter — not the committed value.
            // Use select.value as the pinned selection; only fall back to input when not filtering (initial open).
            var currentSelectedValue;
            if (isRixoInlineTreeCombo) {
                currentSelectedValue = (select.value || '').trim();
                if (!currentSelectedValue && !searchLower) {
                    currentSelectedValue = (input.value || '').trim();
                }
            } else {
                currentSelectedValue = (select.value || input.value || '').trim();
            }
            
            // For chassis fields, extract prefix before "-" for searching
            // This allows users to type "B43W-123456" and it will search for "B43W" only
            var isChassisField = (selectId === 'chassis' || selectId === 'editChassis');
            var searchPrefix = searchLower;
            if (isChassisField && searchLower.indexOf('-') !== -1) {
                searchPrefix = searchLower.substring(0, searchLower.indexOf('-')).trim();
            }
            
            var isMappingMasterCombo = (window.__chassisMasterComboIds && window.__chassisMasterComboIds.indexOf(selectId) !== -1) ||
                (window.__supplierMasterComboIds && window.__supplierMasterComboIds.indexOf(selectId) !== -1);
            
            var filteredOptions = allOptions.filter(function(opt) {
                if (opt.value === '__CHASSIS_MASTER_SEP__') return false;
                if (!searchLower) return true;
                var optText = (opt.text || opt.value || '').toLowerCase();
                // For chassis fields, match against prefix only
                if (isChassisField) {
                    var optPrefix = optText.indexOf('-') !== -1 ? optText.substring(0, optText.indexOf('-')).trim() : optText;
                    return optPrefix.indexOf(searchPrefix) !== -1 || optText.indexOf(searchPrefix) !== -1;
                } else {
                    return optText.indexOf(searchLower) !== -1;
                }
            });
            
            // For chassis: match selected value by prefix (before "-") and case-insensitive
            var currentPrefix = currentSelectedValue;
            if (isChassisField && currentSelectedValue.indexOf('-') !== -1) {
                currentPrefix = currentSelectedValue.substring(0, currentSelectedValue.indexOf('-')).trim();
            }
            var currentLower = (currentSelectedValue || '').toLowerCase();
            var currentPrefixLower = (currentPrefix || '').toLowerCase();
            
            function chassisOptionMatchesSelected(opt) {
                var optVal = (opt.value || '').trim();
                var optText = (opt.text || opt.value || '').trim();
                var optLower = optVal.toLowerCase();
                if (!currentSelectedValue) return false;
                if (optVal === currentSelectedValue || optText === currentSelectedValue) return true;
                if (optLower === currentLower || optLower === currentPrefixLower) return true;
                if (currentPrefixLower && (optLower.indexOf(currentPrefixLower) === 0 || currentPrefixLower.indexOf(optLower) === 0)) return true;
                return false;
            }
            
            // Never treat "See More" as selected; for Brand and master fields (Venue ID, Vehicle type, Rixo Company, Stock Location, POL) use case-insensitive match
            var isMasterOrBrandField = (selectId === 'brand' || selectId === 'editBrand' || (typeof isMasterFieldWithSeeMore === 'function' && isMasterFieldWithSeeMore(selectId)) || isRixoInlineTreeCombo);
            function optionMatchesSelected(opt) {
                if (opt.value === '__SEE_MORE__' || opt.value === '__SEE_LESS__') return false;
                if (opt.value === '__CHASSIS_MASTER_SEP__') return false;
                if (!currentSelectedValue) return false;
                if (opt.value === currentSelectedValue || (opt.text || '') === currentSelectedValue) return true;
                if (isChassisField) return chassisOptionMatchesSelected(opt);
                if (isMasterOrBrandField) return (opt.value || '').toLowerCase() === currentLower || (opt.text || '').toLowerCase() === currentLower;
                return false; // other fields: exact match only (already checked above)
            }
            
            var orderedOptions;
            if (isMappingMasterCombo) {
                function sepPullToFront(arr, sel) {
                    if (!sel || !arr || arr.length === 0) return arr.slice();
                    var ix = -1;
                    for (var j = 0; j < arr.length; j++) {
                        if (arr[j].value === sel.value) { ix = j; break; }
                    }
                    if (ix <= 0) return arr.slice();
                    var copy = arr.slice();
                    var first = copy.splice(ix, 1)[0];
                    return [first].concat(copy);
                }
                var sepIdx = -1;
                for (var i = 0; i < allOptions.length; i++) {
                    if (allOptions[i].value === '__CHASSIS_MASTER_SEP__') { sepIdx = i; break; }
                }
                var chassisPart = sepIdx >= 0 ? allOptions.slice(0, sepIdx) : allOptions.slice();
                var masterPart = sepIdx >= 0 ? allOptions.slice(sepIdx + 1) : [];
                function filterCm(arr) {
                    if (!searchLower) return arr.slice();
                    return arr.filter(function(opt) {
                        var optText = (opt.text || opt.value || '').toLowerCase();
                        return optText.indexOf(searchLower) !== -1;
                    });
                }
                var chF = filterCm(chassisPart);
                var mF = filterCm(masterPart);
                var selectedOption = null;
                if (currentSelectedValue) {
                    allOptions.forEach(function(opt) {
                        if (optionMatchesSelected(opt)) selectedOption = opt;
                    });
                }
                if (selectedOption) {
                    chF = sepPullToFront(chF, selectedOption);
                    mF = sepPullToFront(mF, selectedOption);
                }
                orderedOptions = [];
                chF.forEach(function(o) { orderedOptions.push(o); });
                if (chF.length && mF.length && sepIdx >= 0) {
                    orderedOptions.push({ value: '__CHASSIS_MASTER_SEP__', text: '', disabled: true });
                }
                mF.forEach(function(o) { orderedOptions.push(o); });
            } else {
            // Separate selected value from other options
            var selectedOption = null;
            var otherOptions = [];
            
            // First, try to find selected option in filtered options
            filteredOptions.forEach(function(opt) {
                var isMatch = optionMatchesSelected(opt);
                if (isMatch) {
                    selectedOption = opt;
                } else {
                    otherOptions.push(opt);
                }
            });
            
            // If selected value not found in filtered options, check all options
            if (!selectedOption && currentSelectedValue) {
                allOptions.forEach(function(opt) {
                    if (optionMatchesSelected(opt)) selectedOption = opt;
                });
            }
            
            // Rebuild options array: selected first (if exists), then others
            orderedOptions = [];
            if (selectedOption) {
                // For chassis: always show selected at top when it matches by prefix/case; for others use filter
                var selectedMatchesFilter = !searchLower || 
                    selectedOption.value.toLowerCase().indexOf(searchLower) !== -1 || 
                    (selectedOption.text || '').toLowerCase().indexOf(searchLower) !== -1;
                if (isChassisField) {
                    selectedMatchesFilter = !searchPrefix || 
                        selectedOption.value.toLowerCase().indexOf(searchPrefix) !== -1 || 
                        (selectedOption.text || '').toLowerCase().indexOf(searchPrefix) !== -1 ||
                        chassisOptionMatchesSelected(selectedOption);
                }
                
                if (selectedMatchesFilter) {
                    orderedOptions.push(selectedOption);
                    console.log('🔵 [DROPDOWN] Selected value "' + currentSelectedValue + '" will appear at top of dropdown');
                } else if (isChassisField) {
                    // For chassis: always show selected at top so we never show "No matches found" after user selects
                    orderedOptions.push(selectedOption);
                    console.log('🔵 [DROPDOWN] Chassis selected value "' + currentSelectedValue + '" at top of dropdown');
                } else {
                    console.log('[DROPDOWN] Selected value "' + currentSelectedValue + '" does not match filter, hiding it');
                }
            } else if (currentSelectedValue) {
                console.warn('[DROPDOWN] Selected value "' + currentSelectedValue + '" not found in options list');
            }
            // Add all other filtered options (excluding the selected one if it was already added)
            otherOptions.forEach(function(opt) {
                if (!selectedOption || opt.value !== selectedOption.value) {
                    orderedOptions.push(opt);
                }
            });
            }
            
            // Clear existing options
            dropdown.innerHTML = '';
            
            // Add filtered options (for chassis with selectedOption we already added it above, so no "No matches found")
            if (orderedOptions.length === 0 && searchLower) {
                var noResults = document.createElement('div');
                noResults.style.padding = '12px';
                noResults.style.textAlign = 'center';
                noResults.style.color = '#666666';
                noResults.style.fontSize = '14px';
                noResults.textContent = 'No matches found';
                dropdown.appendChild(noResults);
            } else {
                orderedOptions.forEach(function(opt, index) {
                    if (opt.value === '__CHASSIS_MASTER_SEP__') {
                        var sepRow = document.createElement('div');
