                        } else {
                            dropdownEl.style.maxHeight = '300px';
                        }
                    }
                    
                    // Car Brand modal (Fuel/Shift): always cap to modal boundary and force scroll
                    if (selectId === 'carBrandFuel' || selectId === 'carBrandShift') {
                        var modalContent = document.getElementById('carBrandModalContent');
                        if (modalContent) {
                            var mcRect = modalContent.getBoundingClientRect();
                            var spaceBelowModal = mcRect.bottom - rect.bottom - 16;
                            var currentMax = parseInt(dropdownEl.style.maxHeight, 10) || 250;
                            var capped = (spaceBelowModal > 0) ? Math.min(currentMax, spaceBelowModal) : 180;
                            dropdownEl.style.maxHeight = capped + 'px';
                            dropdownEl.style.overflowY = 'auto';
                            dropdownEl.style.overflowX = 'hidden';
                            dropdownEl.style.webkitOverflowScrolling = 'touch';
                        }
                    }
                });
            });
            
            // Ensure dropdown is always scrollable
            dropdown.style.overflowY = 'auto';
            dropdown.style.overflowX = 'hidden';
            dropdown.style.webkitOverflowScrolling = 'touch';
            
            // Add input event handler to filter dropdown based on typed text
            // When value is cleared, show all options (don't close dropdown)
            var inputHandler = function(e) {
                var searchText = input.value || '';
                
                // Sync select value with input value
                // If input is cleared, clear select too
                if (select) {
                    if (!searchText || searchText.trim() === '') {
                        select.value = '';
                } else {
                        // Try to match select value with input value
                        var matchingOption = Array.from(select.options).find(function(opt) {
                            return opt.value === searchText;
                        });
                        if (matchingOption) {
                            select.value = searchText;
                        }
                    }
                }
                
                // Filter dropdown based on search text
                // If empty, show all options; if typed, show filtered options
                filterComboboxDropdown(selectId, searchText);
            };
            input.addEventListener('input', inputHandler);
            
            // Store handler reference for cleanup
            dropdown.dataset.inputHandler = 'attached';
            
            // Add focus handler to ensure dropdown is open and showing all options when focused
            var focusHandler = function(e) {
                // For chassis dropdowns, ensure options are loaded first
                if (selectId === 'chassis' || selectId === 'editChassis') {
                    // Check if select has options (more than just the default option)
                    if (select.options.length <= 1) {
                        // Check if already loading to prevent recursion
                        var loadingKey = selectId + '_loading';
                        if (window[loadingKey]) {
                            return;
                        }
                        console.log('🔄 Chassis input focused but options not loaded, loading all chassis...');
                        var isEditForm = selectId === 'editChassis';
                        if (typeof window.loadAllChassisDropdown === 'function') {
                            window[loadingKey] = true;
                            window.loadAllChassisDropdown(isEditForm);
                            setTimeout(function() {
                                window[loadingKey] = false;
                                openComboboxDropdown(selectId);
                            }, 500);
                        } else {
                            // Fallback: try to open anyway
                            openComboboxDropdown(selectId);
                        }
                        return;
                    }
                }
                
                // If dropdown doesn't exist, open it
                var existingDropdown = document.getElementById(selectId + '_dropdown');
                if (!existingDropdown) {
                    openComboboxDropdown(selectId);
                } else {
                    // Dropdown exists, refresh it to show all options if input is empty
                    var searchText = input.value || '';
                    filterComboboxDropdown(selectId, searchText);
                }
            };
            input.addEventListener('focus', focusHandler);
            
            // Add click handler to ensure dropdown opens when clicking on input
            // This helps when input is cleared and user clicks on it again
            var clickHandler = function(e) {
                // For chassis dropdowns, ensure options are loaded first
                if (selectId === 'chassis' || selectId === 'editChassis') {
                    // Check if select has options (more than just the default option)
                    if (select.options.length <= 1) {
                        // Check if already loading to prevent recursion
                        var loadingKey = selectId + '_loading';
                        if (window[loadingKey]) {
                            return;
                        }
                        Logger.debug("Chassis input clicked but options not loaded, loading all chassis...");
                        var isEditForm = selectId === 'editChassis';
                        if (typeof window.loadAllChassisDropdown === 'function') {
                            window[loadingKey] = true;
                            window.loadAllChassisDropdown(isEditForm);
                            setTimeout(function() {
                                window[loadingKey] = false;
                                openComboboxDropdown(selectId);
                            }, 500);
                        } else {
                            // Fallback: try to open anyway
                            openComboboxDropdown(selectId);
                        }
                        return;
                    }
                }
                
                // Open dropdown if not already open
                var existingDropdown = document.getElementById(selectId + '_dropdown');
                if (!existingDropdown) {
                    openComboboxDropdown(selectId);
                } else {
                    // Refresh dropdown to show all options based on current input value
                    var searchText = input.value || '';
                    filterComboboxDropdown(selectId, searchText);
                }
            };
            input.addEventListener('click', clickHandler);
            
            // Add blur handler to close dropdown when input loses focus
            // But only if user clicked outside (not on dropdown or button)
            var blurHandler = function(e) {
                // Small delay to allow click events on dropdown to process first
                setTimeout(function() {
                    var dropdown = document.getElementById(selectId + '_dropdown');
                    var activeElement = document.activeElement;
                    
                    // Don't close if:
                    // - User clicked on dropdown
                    // - User clicked on dropdown button
                    // - User clicked on select element
                    // - User clicked on input (shouldn't happen, but check anyway)
                    if (dropdown && 
                        activeElement &&
                        !dropdown.contains(activeElement) &&
                        activeElement.id !== selectId + 'Button' &&
                        activeElement.id !== selectId &&
                        activeElement.id !== inputId) {
                        // User clicked outside - close dropdown
                        closeComboboxDropdown(selectId);
                    }
                }, 250);
            };
            input.addEventListener('blur', blurHandler);
            
            // Add click outside handler - close dropdown only when clicking truly outside
            var closeHandler = function(e) {
                var target = e.target;
                // Clicks on ▼ text hit a Text node — normalize to parent so id/closest checks work
                if (target && target.nodeType === 3 && target.parentElement) {
                    target = target.parentElement;
                }
                // Don't close if clicking on:
                // - The dropdown itself
                // - The dropdown button
                // - The select element
                // - The input field
                // - Any element inside the dropdown
                if (dropdown.contains(target) || 
                    target.id === selectId + 'Button' || 
                    target.id === selectId ||
                    target.id === inputId ||
                    (target.closest && target.closest('#' + dropdown.id))) {
                    return; // Don't close
                }
                // Clicked outside - close dropdown
                closeComboboxDropdown(selectId);
                document.removeEventListener('click', closeHandler);
            };
            setTimeout(function() {
                document.addEventListener('click', closeHandler);
            }, 10);
            
            // Prevent page scrolling when dropdown is open (but allow dropdown to scroll)
            // Store original overflow state
            var originalBodyOverflow = document.body.style.overflow || '';
            var originalHtmlOverflow = document.documentElement.style.overflow || '';
            
            // DON'T set overflow to hidden - it prevents dropdown scrolling
            // Instead, we'll handle scroll events to close dropdowns
            dropdown.dataset.originalBodyOverflow = originalBodyOverflow;
            dropdown.dataset.originalHtmlOverflow = originalHtmlOverflow;
            
            // Ensure dropdown can always scroll by setting explicit styles
            dropdown.style.overflowY = 'auto';
            dropdown.style.overflowX = 'hidden';
            dropdown.style.webkitOverflowScrolling = 'touch'; // Smooth scrolling on iOS
            
            // Close dropdown when page is scrolled (but allow scrolling inside dropdown)
            var scrollHandler = function(e) {
                // Check if scroll happened inside the dropdown
                var scrollTarget = e.target;
                if (!scrollTarget) scrollTarget = document.body;
                
                // Allow scrolling inside the dropdown itself - check multiple ways
                if (dropdown.contains(scrollTarget) || 
                    dropdown === scrollTarget ||
                    scrollTarget.closest && scrollTarget.closest('#' + dropdown.id)) {
                    // User is scrolling inside dropdown - allow it and don't close
                    e.stopPropagation();
                    return;
                }
                
                // Page is scrolling - close dropdown
                // Remove listeners first to prevent conflicts
                window.removeEventListener('scroll', scrollHandler, true);
                document.removeEventListener('scroll', scrollHandler, true);
                // Close dropdown
                closeComboboxDropdown(selectId);
            };
            
            // Prevent dropdown scroll from bubbling
            dropdown.addEventListener('scroll', function(e) {
                e.stopPropagation();
            }, true);
            
            window.addEventListener('scroll', scrollHandler, true);
            document.addEventListener('scroll', scrollHandler, true);
            
            // Also close on window resize
            var resizeHandler = function() {
                window.removeEventListener('resize', resizeHandler);
                // Close dropdown (this will restore scrolling)
                closeComboboxDropdown(selectId);
            };
            window.addEventListener('resize', resizeHandler);
        };
        
        // Function to ensure scrolling is restored
        window.ensureScrollingRestored = function() {
            var allDropdowns = document.querySelectorAll('[id$="_dropdown"]');
            if (allDropdowns.length === 0) {
                // No dropdowns open, ALWAYS restore scrolling
                document.body.style.overflow = '';
                document.body.style.overflowX = '';
                document.body.style.overflowY = '';
                document.documentElement.style.overflow = '';
                document.documentElement.style.overflowX = '';
                document.documentElement.style.overflowY = '';
            }
        };
        
        // Function to close combobox dropdown
        window.closeComboboxDropdown = function(selectId) {
            var dropdown = document.getElementById(selectId + '_dropdown');
            if (dropdown) {
                // Remove any stored event handlers
                var inputId = selectId + 'Input';
                if (selectId === 'rixoPriceDropdown') {
                    inputId = 'rixoPriceInput';
                } else if (selectId === 'editRixoPriceDropdown') {
                    inputId = 'editRixoPriceInput';
                }
                
                // Remove the dropdown
                dropdown.remove();
            }
            
            // ALWAYS ensure scrolling is restored after closing any dropdown
            window.ensureScrollingRestored();
        };
        
        // Close all dropdowns when page is scrolled (but allow scrolling inside dropdown)
        // Use a single, robust scroll handler
        var globalScrollHandler = function(e) {
            // Find all open dropdowns
            var allDropdowns = document.querySelectorAll('[id$="_dropdown"]');
            if (allDropdowns.length === 0) {
                // No dropdowns, ensure scrolling is enabled
                window.ensureScrollingRestored();
                return;
            }
            
            var scrollTarget = e.target || document.body;
            var shouldClose = false;
            
            allDropdowns.forEach(function(dropdown) {
                // Don't close if scrolling inside the dropdown itself
                // Check multiple ways to detect if scroll is inside dropdown
                if (!dropdown.contains(scrollTarget) && 
                    dropdown !== scrollTarget &&
                    (!scrollTarget.closest || !scrollTarget.closest('#' + dropdown.id))) {
                    // Page is scrolling, not dropdown - mark for closing
                    shouldClose = true;
                } else {
                    // Scrolling inside dropdown - stop propagation
                    e.stopPropagation();
                }
            });
            
            // If we should close dropdowns, close them all
            if (shouldClose) {
                allDropdowns.forEach(function(dropdown) {
                    dropdown.remove();
                });
                window.ensureScrollingRestored();
            }
        };
        
        // Add scroll listeners (use capture phase to catch all scroll events)
        // But be careful not to interfere with dropdown scrolling
        window.addEventListener('scroll', globalScrollHandler, true);
        document.addEventListener('scroll', globalScrollHandler, true);
        
        // Close all dropdowns when window is resized
        window.addEventListener('resize', function() {
            var allDropdowns = document.querySelectorAll('[id$="_dropdown"]');
            allDropdowns.forEach(function(dropdown) {
                dropdown.remove();
            });
        });
        
        // Sync input to select when user types and filter dropdown
        document.addEventListener('input', function(e) {
            if (e.target.id && e.target.id.endsWith('Input')) {
                var selectId = e.target.id.replace('Input', '');
                
                // Handle special cases
                if (e.target.id === 'rixoPriceInput') {
                    selectId = 'rixoPriceDropdown';
                } else if (e.target.id === 'editRixoPriceInput') {
                    selectId = 'editRixoPriceDropdown';
                }
                
                // Filter dropdown if it's open
                var dropdown = document.getElementById(selectId + '_dropdown');
                if (dropdown) {
                    filterComboboxDropdown(selectId, e.target.value);
                } else {
                    // If dropdown is not open and user is typing, open it
                    var select = document.getElementById(selectId);
                    if (select && select.options && select.options.length > 1) {
                        openComboboxDropdown(selectId);
                    }
                }
                
                // Also sync the select value if it matches an option
                var select = document.getElementById(selectId);
                if (select) {
                    var matchingOption = Array.from(select.options).find(function(opt) {
                        return opt.value === e.target.value || opt.text === e.target.value;
                    });
                    if (matchingOption) {
                        select.value = matchingOption.value;
                    }
                }
                var select = document.getElementById(selectId);
                if (select) {
                    // Check if typed value matches any option
                    var matchingOption = Array.from(select.options).find(function(opt) {
                        return opt.value === e.target.value;
                    });
                    if (matchingOption) {
                        select.value = e.target.value;
                    }
                }
            }
        });
    """).unsafeCast<Unit>()
}

