// JavaScript functions for Rixo dropdown functionality

/** API may send `carPictures` or `car_pictures`; some payloads use a JSON string or an array. */
private fun carPicturesFieldFromPurchase(p: dynamic): dynamic {
    if (p == null || p == js("undefined")) return null
    val camel = js("p.carPictures")
    if (camel != null && camel != js("undefined")) {
        // Empty camel string must not hide a populated `car_pictures` (some serializers send both).
        val camelEmptyStr = js("typeof camel === 'string' && String(camel).trim() === ''").unsafeCast<Boolean>()
        if (!camelEmptyStr) return camel
    }
    return js("p.car_pictures")
}

/**
 * Some environments return snake_case keys. Forms, loadExistingCarPictures, and comparisons expect camelCase.
 */
private fun normalizeApiPurchaseForClient(p: dynamic) {
    if (p == null || p == js("undefined")) return
    if (js(
            "((p.carPictures === undefined || p.carPictures === null) || " +
                "(typeof p.carPictures === 'string' && String(p.carPictures).trim() === '')) && " +
                "p.car_pictures != null && String(p.car_pictures).trim() !== ''"
        ).unsafeCast<Boolean>()
    ) {
        p.carPictures = js("p.car_pictures")
    }
    if (js("(p.venueId === undefined || p.venueId === null) && p.venue_id != null").unsafeCast<Boolean>()) {
        p.venueId = js("p.venue_id")
    }
    if (js("(p.stockLocation === undefined || p.stockLocation === null) && p.stock_location != null").unsafeCast<Boolean>()) {
        p.stockLocation = js("p.stock_location")
    }
    if (js("(p.auctionHouse === undefined || p.auctionHouse === null) && p.auction_house != null").unsafeCast<Boolean>()) {
        p.auctionHouse = js("p.auction_house")
    }
    if (js("(p.rixoCompany === undefined || p.rixoCompany === null) && p.rixo_company != null").unsafeCast<Boolean>()) {
        p.rixoCompany = js("p.rixo_company")
    }
    if (js("(p.clientName === undefined || p.clientName === null) && p.client_name != null").unsafeCast<Boolean>()) {
        p.clientName = js("p.client_name")
    }
    if (js("(p.carModelYear === undefined || p.carModelYear === null) && p.car_model_year != null").unsafeCast<Boolean>()) {
        p.carModelYear = js("p.car_model_year")
    }
    if (js("(p.manufactureYear === undefined || p.manufactureYear === null) && p.manufacture_year != null").unsafeCast<Boolean>()) {
        p.manufactureYear = js("p.manufacture_year")
    }
    if (js("(p.bookingId === undefined || p.bookingId === null) && p.booking_id != null").unsafeCast<Boolean>()) {
        p.bookingId = js("p.booking_id")
    }
    if (js("(p.shipmentSize === undefined || p.shipmentSize === null) && p.shipment_size != null").unsafeCast<Boolean>()) {
        p.shipmentSize = js("p.shipment_size")
    }
    if (js("(p.paymentDate === undefined || p.paymentDate === null) && p.payment_date != null").unsafeCast<Boolean>()) {
        p.paymentDate = js("p.payment_date")
    }
    if (js("(p.shipmentDate === undefined || p.shipmentDate === null) && p.shipment_date != null").unsafeCast<Boolean>()) {
        p.shipmentDate = js("p.shipment_date")
    }
    if (js("(p.blNo === undefined || p.blNo === null) && p.bl_no != null").unsafeCast<Boolean>()) {
        p.blNo = js("p.bl_no")
    }
    if (js("(p.bookingRequested === undefined || p.bookingRequested === null) && p.booking_requested != null").unsafeCast<Boolean>()) {
        p.bookingRequested = js("p.booking_requested")
    }
}

/** After supplier/rixo async mapping settles, baseline must match the form or Venue/Stock look "changed" when only pictures were edited. */
private fun finalizeEditFormOriginalBaselineFromDom() {
    if (document.getElementById("editForm") == null) return
    if (originalPurchaseData == null) return
    try {
        val baseline = collectCurrentEditFormData()
        // Registration Date baseline always from API snapshot — never typed DOM (avoids false "no change").
        baseline.carModelYear = editCarModelYearApiBaseline()
        originalPurchaseData = JSON.parse(JSON.stringify(baseline))
    } catch (e: Throwable) {
        console.log("finalizeEditFormOriginalBaselineFromDom:", e.message)
    }
}

/** After existing thumbnails are in the DOM, baseline must match collectCarPictures() or every edit looks "changed". */
private fun syncOriginalPurchaseCarPicturesBaselineFromDom() {
    val snap = originalPurchaseData ?: return
    snap.carPictures = collectCarPictures()
}

fun setEditFormValuesFromKotlin(purchaseData: dynamic) {
    normalizeApiPurchaseForClient(purchaseData)
    js("window.__editRixoFieldOverrides = {}; window.__suppressRixoAutoSelect = false; window.__editCarModelYearUserEdited = false;")
    // Store original purchase data for comparison (deep copy). Huge base64 in carPictures can make stringify fail or stall.
    originalPurchaseData = try {
        JSON.parse(JSON.stringify(purchaseData))
    } catch (e: Throwable) {
        console.warn("originalPurchaseData deep copy failed, using shallow reference:", e.message)
        purchaseData
    }
    // Unify snake_case API field so snapshot has carPictures (same as fetch object)
    val snap = originalPurchaseData
    if (snap != null) {
        val raw = carPicturesFieldFromPurchase(snap)
        if (raw != null && raw != js("undefined")) {
            snap.carPictures = raw
        }
        val cmCanonical = normalizeCarModelYearForCompare(snap.carModelYear?.toString())
        if (cmCanonical.isNotEmpty()) {
            snap.carModelYear = cmCanonical
        }
        window.asDynamic().__editCarModelYearBaseline = cmCanonical
    }
    
    val dataToPass = purchaseData
    js("""
        try {
            if (window.setEditFormValues && typeof window.setEditFormValues === 'function') {
                window.setEditFormValues(dataToPass);
            } else {
                Logger.debug("setEditFormValues not available yet, skipping...");
            }
        } catch (e) {
            console.log('Error calling setEditFormValues:', e);
        }
    """)
    prefillEditNumberCutDetailFields(purchaseData.numberCut)
}
fun setupRixoDropdowns() {
    window.asDynamic().populateSupplierAuctionNameDropdownsFromRixoPricesApi = {
        populateSupplierAuctionNameDropdownsFromRixoPricesApi()
    }
    js("""
        // Dynamic dropdown system with hierarchical filtering
        var populateRetryCount = 0;
        var maxPopulateRetries = 20; // 10 seconds max wait (20 * 500ms)
        
        function populateDropdownOptions() {
            if (typeof window.rixoPriceMapping === 'undefined') {
                populateRetryCount++;
                if (populateRetryCount >= maxPopulateRetries) {
                    console.error('❌ Rixo price mapping failed to load after', maxPopulateRetries * 500, 'ms. Check if rixo-price-mapping.js is loaded correctly.');
                    if (typeof window.refreshRixoDropdowns === 'function') {
                        console.log('Attempting to load from backend API as fallback...');
                        window.refreshRixoDropdowns();
                    }
                    return Promise.resolve();
                }
                console.log('Rixo price mapping not loaded yet, retrying in 500ms... (attempt', populateRetryCount, 'of', maxPopulateRetries, ')');
                return new Promise(function(resolve) {
                    setTimeout(function() {
                        populateDropdownOptions().then(resolve);
                    }, 500);
                });
            }
            
            // Reset retry count on success
            populateRetryCount = 0;
            
            var mappingKeys = Object.keys(window.rixoPriceMapping || {});
            console.log('✅ Rixo price mapping loaded,', mappingKeys.length, 'top-level mapping entries (used for cascading; supplier list from rixo_prices API)');
            
            if (mappingKeys.length === 0) {
                console.warn('⚠️ Rixo price mapping is empty! Check rixo-price-mapping.js file.');
            }
            
            function finishPopulateDropdownOptions() {
            // Clear supplier-dependent dropdowns (all cleared together so rebuild is consistent)
            clearDropdown('typeOfVehicle');
            clearDropdown('editTypeOfVehicle');
            clearDropdown('stockLocation');
            clearDropdown('editStockLocation');
            clearDropdown('venueId');
            clearDropdown('editVenueId');
            clearDropdown('pol');
            clearDropdown('editPol');
            clearDropdown('rixoCompany');
            clearDropdown('editRixoCompany');
            clearDropdown('rixoPrice');
            clearDropdown('editRixoPrice');

            function firstSemicolonTokenJs(v) {
                if (v == null || v === undefined) return '';
                var s = String(v).trim();
                if (!s) return '';
                var parts = s.split(';').map(function(x) { return x.trim(); }).filter(function(x) { return x.length > 0; });
                return parts.length ? parts[0] : s;
            }

            function resolveEditSupplierRebuildSnapshot() {
                if (!document.getElementById('editForm')) return null;
                var snap = null;
                if (typeof window.__snapshotSupplierFormForPreserve === 'function') {
                    snap = window.__snapshotSupplierFormForPreserve();
                }
                var pd = window.__editPurchaseDataForRixo;
                var auction = '';
                if (snap && snap.auction) auction = String(snap.auction).trim();
                if (!auction && pd) auction = (pd.auctionHouse || '').toString().trim();
                if (!auction && typeof window.getComboboxValue === 'function') {
                    auction = (window.getComboboxValue('editAuctionName') || '').trim();
                }
                if (!auction || auction === '__add_new_supplier__') return null;
                if (!snap) snap = {};
                snap.auction = auction;
                snap.isEdit = true;
                if (!snap.stock && pd) snap.stock = firstSemicolonTokenJs(pd.stockLocation || pd.stock_location);
                if (!snap.venue && pd) snap.venue = firstSemicolonTokenJs(pd.venueId || pd.venue_id);
                if (!snap.rixo && pd) snap.rixo = firstSemicolonTokenJs(pd.rixoCompany || pd.rixo_company);
                if (!snap.pol && pd) snap.pol = firstSemicolonTokenJs(pd.pol);
                return snap;
            }

            function reapplySupplierDropdownsFromCurrentAuction() {
                var auction = '';
                var preserveSnap = null;
                if (document.getElementById('editForm')) {
                    preserveSnap = resolveEditSupplierRebuildSnapshot();
                    if (preserveSnap) auction = preserveSnap.auction;
                }
                if (!auction && typeof window.getComboboxValue === 'function') {
                    if (document.getElementById('editAuctionName')) {
                        auction = (window.getComboboxValue('editAuctionName') || '').trim();
                    } else if (document.getElementById('auctionName')) {
                        auction = (window.getComboboxValue('auctionName') || '').trim();
                    }
                }
                if (!auction || auction === '__add_new_supplier__') return;
                if (typeof window.rebuildSupplierDependentDropdowns === 'function') {
                    var rebuildOpts = {
                        autoSelect: false,
                        restoreDelay: document.getElementById('editForm') ? 0 : 80
                    };
                    if (preserveSnap) {
                        rebuildOpts.preserveSnapshot = preserveSnap;
                    } else {
                        rebuildOpts.restoreValues = true;
                    }
                    window.rebuildSupplierDependentDropdowns(auction, rebuildOpts);
                    if (preserveSnap && preserveSnap.stock && typeof window.fetchPolsByStockLocationAndUpdate === 'function') {
                        var mp = (typeof window.getPolTokensFromRixoMappingForSupplier === 'function')
                            ? window.getPolTokensFromRixoMappingForSupplier(auction) : null;
                        window.fetchPolsByStockLocationAndUpdate(auction, preserveSnap.stock, false, mp).catch(function() {});
                    }
                } else if (typeof window.autoSelectRelatedFields === 'function') {
                    window.autoSelectRelatedFields(auction, 'auctionHouse', auction);
                }
            }
            reapplySupplierDropdownsFromCurrentAuction();

            // Always populate Vehicle type from master_menu/type_of_vehicle.
            // Mapping may suggest values, but base options must come from master data.
            window.fetch(apiUrl("master-menu/type_of_vehicle"))
                .then(function(resp) {
                    return resp && resp.ok ? resp.json() : [];
                })
                .then(function(raw) {
                    var values = [];
                    if (Array.isArray(raw)) {
                        values = raw
                            .map(function(v) { return (v || '').toString().trim(); })
                            .filter(function(v) { return v.length > 0; });
                    }
                    if (typeof window.updateDropdown === 'function') {
                        window.updateDropdown('shipmentSize', 'editShipmentSize', values, false);
                    }
                })
                .catch(function(err) {
                    console.warn('Failed to load type_of_vehicle master data:', err);
                });
            }
            
            return new Promise(function(resolve) {
                function finishAndResolve() {
                    finishPopulateDropdownOptions();
                    resolve();
                }
                var loadAuction = window.populateSupplierAuctionNameDropdownsFromRixoPricesApi;
                if (typeof loadAuction === 'function') {
                    var pr = loadAuction();
                    if (pr && typeof pr.then === 'function') {
                        pr.then(finishAndResolve).catch(function(err) {
                            console.warn('Supplier (auction) names from rixo_prices:', err);
                            finishAndResolve();
                        });
                    } else {
                        finishAndResolve();
                    }
                } else {
                    console.warn('populateSupplierAuctionNameDropdownsFromRixoPricesApi not registered');
                    finishAndResolve();
                }
            });
        }
        
        function clearDropdown(elementId) {
            if (window.__supplierMasterComboIds) {
                window.__supplierMasterComboIds = window.__supplierMasterComboIds.filter(function(id) { return id !== elementId; });
            }
            var select = document.getElementById(elementId);
            if (select) {
                select.innerHTML = '<option value="">Select ' + getFieldLabel(elementId) + '</option>';
            }
        }
        
        function getFieldLabel(elementId) {
            switch(elementId) {
                case 'venueId':
                case 'editVenueId':
                    return 'Venue ID';
                case 'typeOfVehicle':
                case 'editTypeOfVehicle':
                case 'shipmentSize':
                case 'editShipmentSize':
                    return 'Vehicle type';
                case 'stockLocation':
                case 'editStockLocation':
                    return 'Stock Location';
                case 'pol':
                case 'editPol':
                    return 'POL';
                case 'rixoCompany':
                case 'editRixoCompany':
                    return 'Rixo Company';
                case 'rixoPrice':
                case 'editRixoPrice':
                    return 'Rixo Price';
                default:
                    return 'Option';
            }
        }
        
        function isMasterFieldWithSeeMore(elementId) {
            if (/^rixo-inline-path-/.test(elementId) || /^rixoLeafInline_/.test(elementId)) return true;
            return elementId === 'venueId' || elementId === 'editVenueId' ||
                elementId === 'shipmentSize' || elementId === 'editShipmentSize' ||
                elementId === 'typeOfVehicle' || elementId === 'editTypeOfVehicle' ||
                elementId === 'fuel' || elementId === 'editFuel' ||
                elementId === 'shift' || elementId === 'editShift' ||
                elementId === 'rixoCompany' || elementId === 'editRixoCompany' ||
                elementId === 'stockLocation' || elementId === 'editStockLocation' ||
                elementId === 'pol' || elementId === 'editPol' ||
                elementId === 'country' || elementId === 'editCountry';
        }
        
        // Ensure saved value exists as an option so validation passes (Edit form: dropdown may have fewer options than saved value)
        function ensureComboboxOptionExists(selectId, value) {
            if (!value || String(value).trim() === '' || value === '__SEE_MORE__' || value === '__SEE_LESS__') return;
            var select = document.getElementById(selectId);
            if (!select) return;
            var val = String(value).trim();
            if (val.indexOf(';') >= 0) {
                var parts = val.split(';').map(function(s) { return s.trim(); }).filter(function(x) { return x.length > 0; });
                val = parts[0] || val;
            }
            if (val === '__CHASSIS_MASTER_SEP__') return;
            var valLower = val.toLowerCase();
            for (var i = 0; i < select.options.length; i++) {
                var opt = select.options[i];
                if (opt.value === '__SEE_MORE__' || opt.value === '__CHASSIS_MASTER_SEP__') continue;
                if ((opt.value || '').toLowerCase() === valLower || (opt.text || '').toLowerCase() === valLower) return;
            }
            var newOpt = document.createElement('option');
            newOpt.value = val;
            newOpt.textContent = val;
