}

/** One-time: comma formatting + numeric-only for `.money-input` (Add + Edit). Call from [main]. */
fun setupMoneyInputFormattingOnce() {
    js("""
        function _commaIntSanitize(raw) {
            if (raw == null) return '';
            var s = String(raw).trim();
            if (!s) return '';
            return s.replace(/[^0-9]/g, '');
        }
        function _stripKmSuffix(raw) {
            if (raw == null) return '';
            return String(raw).replace(/\s*km\s*$/i, '').trim();
        }
        function _commaIntFormat(raw) {
            var s = _commaIntSanitize(raw);
            if (!s) return '';
            return s.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
        }
        function _commaIntFormatKm(raw) {
            var s = _commaIntFormat(_stripKmSuffix(raw));
            return s ? (s + ' km') : '';
        }
        function _moneySanitize(raw) {
            if (raw == null) return '';
            var s = String(raw).trim();
            if (!s) return '';
            s = s.replace(/[^0-9.]/g, '');
            var parts = s.split('.');
            if (parts.length > 2) {
                s = parts[0] + '.' + parts.slice(1).join('');
                parts = s.split('.');
            }
            if (parts[0]) {
                parts[0] = parts[0].replace(/^0+(?=\\d)/, '');
            }
            if (parts.length === 1) return parts[0] || '';
            return (parts[0] || '0') + '.' + (parts[1] || '');
        }
        function _moneyFormat(raw) {
            var s = _moneySanitize(raw);
            if (!s) return '';
            var parts = s.split('.');
            var intPart = parts[0] || '0';
            var decPart = parts.length > 1 ? parts[1] : '';
            intPart = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
            return decPart ? (intPart + '.' + decPart) : intPart;
        }
        function _moneySanitizeAllowNegative(raw) {
            if (raw == null) return '';
            var s = String(raw).trim();
            if (!s) return '';
            var neg = (s.charAt(0) === '-');
            if (neg) s = s.slice(1).trim();
            s = s.replace(/[^0-9.]/g, '');
            var parts = s.split('.');
            if (parts.length > 2) {
                s = parts[0] + '.' + parts.slice(1).join('');
                parts = s.split('.');
            }
            if (parts[0]) {
                parts[0] = parts[0].replace(/^0+(?=\\d)/, '');
            }
            var core = '';
            if (parts.length === 1) core = parts[0] || '';
            else core = (parts[0] || '0') + '.' + (parts[1] || '');
            if (!core && neg) return '-';
            if (!core) return '';
            return neg ? ('-' + core) : core;
        }
        function _moneyFormatAllowNegative(raw) {
            var s = _moneySanitizeAllowNegative(raw);
            if (!s) return '';
            if (s === '-') return '-';
            var neg = (s.charAt(0) === '-');
            var body = neg ? s.slice(1) : s;
            var parts = body.split('.');
            var intPart = parts[0] || '0';
            var decPart = parts.length > 1 ? parts[1] : '';
            intPart = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
            var out = decPart ? (intPart + '.' + decPart) : intPart;
            return neg ? ('-' + out) : out;
        }
        function _moneyFinalDisplay(el, formatted, useNeg) {
            if (!el.classList || !el.classList.contains('money-empty-as-zero')) return formatted;
            var s = useNeg ? _moneySanitizeAllowNegative(formatted) : _moneySanitize(formatted);
            if (useNeg) {
                if (s === '' || s === '-') return (s === '-') ? '-' : '';
                var pn = parseFloat(s);
                if (!isNaN(pn) && pn === 0) return '';
                return formatted;
            }
            if (s === '') return '';
            var n = parseFloat(s);
            if (!isNaN(n) && n === 0) return '';
            return formatted;
        }
        window._moneySanitize = function(raw) { return _moneySanitize(raw); };
        window._moneyFormat = function(raw) { return _moneyFormat(raw); };
        window._moneySanitizeAllowNegative = function(raw) { return _moneySanitizeAllowNegative(raw); };
        window._moneyFormatAllowNegative = function(raw) { return _moneyFormatAllowNegative(raw); };
        window._commaIntSanitize = function(raw) { return _commaIntSanitize(raw); };
        window._commaIntFormat = function(raw) { return _commaIntFormat(raw); };
        window._plainIntSanitize = function(raw) {
            if (raw == null) return '';
            return String(raw).replace(/[^0-9]/g, '');
        };
        function _bindMoneyDelegation() {
            if (window.__moneyInputListenersV2Installed) return;
