                    var beforePlain = oldPlain.substring(0, selPlain);
                    var digitsBeforePlain = beforePlain.replace(/[^0-9]/g, '').length;
                    var sanitizedPlain = oldPlain.replace(/[^0-9]/g, '');
                    if (sanitizedPlain !== oldPlain) {
