            .then { resp -> resp.json() }
            .then { data: dynamic ->
                val found = (data.found as? Boolean) ?: false
                val rfInput = document.getElementById("recycleFee") as? HTMLInputElement
                if (rfInput != null && found) {
                    val fee = (data.fee ?: "").toString()
                    if (fee.isNotBlank()) {
