// Function to fetch brand mappings and populate dropdowns
// Function to fetch brand mappings ONLY for populating dropdowns (no auto-fill)
// Used when chassis is selected first - populates dropdowns based on the brand from chassis mapping
// mappingValues: values from chassis mapping - if null/empty, preserve existing form values
fun fetchBrandMappingsForDropdowns(
    brandName: String, 
    isEditForm: Boolean = false,
    carName: String? = null,
    fuel: String? = null,
    wd: String? = null,
    shift: String? = null,
    cc: String? = null,
    door: String? = null,
    grade: String? = null
): dynamic {
    if (brandName.isBlank()) {
        console.log("Brand name is blank, skipping brand mappings fetch for dropdowns")
        return js("Promise.resolve()")
    }
    
    val encodedBrandName = js("encodeURIComponent")(brandName) as String
    val url = apiUrl("car-brand-mapping/brand/$encodedBrandName")
    console.log("🔄 Fetching brand mappings for dropdowns only: $brandName")
    
    return window.fetch(url)
        .then { response ->
            if (!response.ok) {
                throw Exception("Failed to fetch brand mappings: ${response.status}")
            }
            response.json()
        }
        .then { data: dynamic ->
            val mappingsData = js("data.mappings")
            val mappings = if (js("Array.isArray(mappingsData)")) {
                (mappingsData as? Array<*>)?.toList() ?: emptyList()
            } else {
                emptyList()
            }
            val dropdowns = js("data.dropdowns")
            
            if (mappings.isEmpty()) {
                console.log("⚠️ No mappings found for brand: $brandName")
                return@then
            }
            
            // Populate dropdowns ONLY (no auto-fill) - this populates car name, fuel, wd, etc. dropdowns
            // Note: Chassis dropdown should NOT be filtered - it should always show all chassis
            // Pass mapping values so dropdowns can preserve existing values when mapping doesn't have a value
            populateBrandDropdownsForChassisFlow(dropdowns, isEditForm, carName, fuel, wd, shift, cc, door, grade)
            
            console.log("✅ Brand dropdowns populated successfully for: $brandName")
            data
        }
        .catch { error ->
            console.error("❌ Error fetching brand mappings for dropdowns:", error)
            js("Promise.reject(error)")
        }
}

fun fetchBrandMappings(brandName: String, isEditForm: Boolean = false): dynamic {
    if (brandName.isBlank()) {
        // Clear dropdowns and form fields if brand is cleared
        clearBrandMappings(isEditForm)
        return js("Promise.resolve()")
    }
    
    val encodedBrandName = js("encodeURIComponent")(brandName) as String
    val url = apiUrl("car-brand-mapping/brand/$encodedBrandName")
    console.log("Fetching brand mappings for: $brandName")
    
    return window.fetch(url)
        .then { response ->
            if (!response.ok) {
                throw Exception("Failed to fetch brand mappings: ${response.status}")
            }
            response.json()
        }
        .then { data: dynamic ->
            val mappingsData = js("data.mappings")
            val mappings = if (js("Array.isArray(mappingsData)")) {
                (mappingsData as? Array<*>)?.toList() ?: emptyList()
            } else {
                emptyList()
            }
            val firstRow = js("data.firstRow")
            val dropdowns = js("data.dropdowns")
            
            if (mappings.isEmpty() || js("firstRow == null")) {
                console.log("No mappings found for brand: $brandName")
                clearBrandMappings(isEditForm)
                return@then
            }
            
            // Populate dropdowns (this will filter chassis dropdown to brand-specific chassis)
            // Note: If chassis was selected first and brand was auto-filled, this will filter chassis dropdown
            // which is correct behavior - user can still see all chassis if they clear brand
            populateBrandDropdowns(dropdowns, isEditForm)
            
            // Auto-fill form fields with first row values for both Add and Edit forms
            // When brand is selected, always auto-fill with first row mapping
            // BUT: Skip auto-fill if this was called from chassis-first flow (to avoid overwriting chassis-selected values)
            val isChassisFirstFlow = js("window.autoFilledBrand != null") as? Boolean ?: false
            if (firstRow != null && !isChassisFirstFlow) {
                console.log("📝 Auto-filling fields with first row data (isEditForm: $isEditForm)")
                console.log("📝 First row data:", firstRow)
                autoFillBrandFields(firstRow, isEditForm)
            } else if (isChassisFirstFlow) {
                console.log("⏭️ Skipping auto-fill - chassis-first flow active (chassis was selected first)")
            } else {
                console.warn("⚠️ No first row data available for auto-fill")
            }
            
            console.log("Brand mappings loaded successfully for: $brandName")
            data
        }
        .catch { error ->
            console.error("Error fetching brand mappings:", error)
            js("Promise.reject(error)")
        }
}

