/**
 * Chassis mapping tokens first, then [CHASSIS_MASTER_SEP_VALUE], then master list from API (deduped).
 * Used for Brand, Fuel, Shift, Vehicle type when Part 1 chassis is selected (Add + Edit purchase).
 */
private fun populateChassisMappingWithMasterListAsync(
    selectId: String,
    defaultLabel: String,
    chassisTokens: List<String>,
    selectedValue: String,
    masterApiPath: String,
    preserveIfEmpty: String = "",
) {
    val select = document.getElementById(selectId) as? HTMLSelectElement ?: return
    val input = document.getElementById("${selectId}Input") as? HTMLInputElement
    registerChassisMasterComboId(selectId)
    select.innerHTML = ""
    val def = document.createElement("option") as HTMLOptionElement
    def.value = ""
    def.textContent = defaultLabel
    select.appendChild(def)
    val chassisLower = mutableSetOf<String>()
    val seen = mutableSetOf<String>()
    for (raw in chassisTokens) {
        for (t in splitSemicolonTokens(raw)) {
            if (t.isNotBlank() && seen.add(t.lowercase())) {
                chassisLower.add(t.lowercase())
                val option = document.createElement("option") as HTMLOptionElement
                option.value = t
                option.textContent = t
                select.appendChild(option)
            }
        }
    }
    val sep = document.createElement("option") as HTMLOptionElement
    sep.value = CHASSIS_MASTER_SEP_VALUE
    sep.textContent = SUPPLIER_MASTER_SEP_OPTION_LABEL
    sep.disabled = true
    select.appendChild(sep)
    val toSet = firstSemicolonToken(
        mergeChassisFieldValue(
            selectedValue.takeIf { it.isNotBlank() } ?: chassisTokens.firstOrNull() ?: "",
            preserveIfEmpty,
        ),
    )
    if (toSet.isNotBlank()) {
        var found = false
        for (i in 0 until select.options.length) {
            val o = select.options.item(i) as? HTMLOptionElement
            if (o != null && o.value == toSet) {
                found = true
                break
            }
        }
        if (!found) {
            val opt = document.createElement("option") as HTMLOptionElement
            opt.value = toSet
            opt.textContent = toSet
            val sepEl = select.options.item(select.options.length - 1) as? HTMLOptionElement
            if (sepEl != null && sepEl.value == CHASSIS_MASTER_SEP_VALUE) {
                select.insertBefore(opt, sepEl)
            } else {
                select.appendChild(opt)
            }
        }
        select.value = toSet
        input?.value = toSet
    } else {
        val keep = preserveIfEmpty.trim()
        if (keep.isNotBlank()) {
            window.asDynamic().__preserveComboId = selectId
            window.asDynamic().__preserveComboVal = keep
            js("""
                if (typeof ensureComboboxOptionExists === 'function') {
                    ensureComboboxOptionExists(window.__preserveComboId, window.__preserveComboVal);
                }
            """)
            select.value = keep
            input?.value = keep
        } else {
            select.value = ""
            input?.value = ""
        }
    }
    syncComboboxFromSelect(selectId)
    val masterSeen = mutableSetOf<String>()
    chassisLower.forEach { masterSeen.add(it) }
    window.fetch(apiUrl(masterApiPath))
        .then { response: dynamic ->
            if (response.ok) response.json() else throw js("Error('Failed to load master list')")
        }
        .then { raw: dynamic ->
            val masterList = parsePurchaseMasterListArray(raw)
            val sel = document.getElementById(selectId) as? HTMLSelectElement ?: return@then
            val inp = document.getElementById("${selectId}Input") as? HTMLInputElement
            for (item in masterList) {
                for (token in splitSemicolonTokens(item)) {
                    if (token.isNotBlank() && masterSeen.add(token.lowercase())) {
                        val option = document.createElement("option") as HTMLOptionElement
                        option.value = token
                        option.textContent = token
                        sel.appendChild(option)
                    }
                }
            }
            val cur = firstSemicolonToken((inp?.value ?: sel.value ?: "").toString())
            if (cur.isNotBlank()) {
                sel.value = cur
                inp?.value = cur
            }
            window.asDynamic().__restoreComboId = selectId
            js("""
                (function() {
                    var id = window.__restoreComboId;
                    if (window.__chassisUserChangeActive === true) {
                        var val = '';
                        if ((id === 'editBrand' || id === 'brand') && window.__chassisMappedBrand) {
                            val = String(window.__chassisMappedBrand);
                        } else if ((id === 'editCarName' || id === 'carName') && window.__chassisMappedCarName) {
                            val = String(window.__chassisMappedCarName);
                        }
                        if (val) {
                            if (typeof ensureComboboxOptionExists === 'function') ensureComboboxOptionExists(id, val);
                            var sel = document.getElementById(id);
                            var inp = document.getElementById(id + 'Input');
                            var valLower = val.toLowerCase();
                            if (sel) {
                                for (var i = 0; i < sel.options.length; i++) {
                                    var o = sel.options[i];
                                    if ((o.value || '').toLowerCase() === valLower) {
                                        sel.value = o.value;
                                        val = o.value;
                                        break;
                                    }
                                }
                                if (!sel.value) sel.value = val;
                            }
                            if (inp) inp.value = val;
                            if (id === 'editBrand' || id === 'brand') {
                                window.isAutoFillingBrand = true;
                                window.autoFilledBrand = val;
                                setTimeout(function() { window.isAutoFillingBrand = false; }, 300);
                            }
                        }
                        return;
                    }
                    if (!window.__editPurchaseHydrating || !window.__editPurchaseSnapshot) return;
                    var snap = window.__editPurchaseSnapshot;
                    var restore = '';
                    if (id === 'editCarName' && snap.carName) {
                        restore = String(snap.carName).split(';').map(function(x) { return x.trim(); }).filter(Boolean)[0] || '';
                    } else if (id === 'editBrand' && (snap.brand || snap.carBrand)) {
                        restore = String(snap.brand || snap.carBrand).split(';').map(function(x) { return x.trim(); }).filter(Boolean)[0] || '';
                    } else if (id === 'carName' && snap.carName) {
                        restore = String(snap.carName).split(';').map(function(x) { return x.trim(); }).filter(Boolean)[0] || '';
                    } else if (id === 'brand' && (snap.brand || snap.carBrand)) {
                        restore = String(snap.brand || snap.carBrand).split(';').map(function(x) { return x.trim(); }).filter(Boolean)[0] || '';
                    }
                    if (!restore) return;
                    var sel = document.getElementById(id);
                    var inp = document.getElementById(id + 'Input');
                    if (typeof ensureComboboxOptionExists === 'function') ensureComboboxOptionExists(id, restore);
                    if (sel) sel.value = restore;
                    if (inp) inp.value = restore;
                })();
            """)
            syncComboboxFromSelect(selectId)
            console.log("✅ Merged master list for $selectId from $masterApiPath")
        }
        .catch { _: dynamic ->
            console.error("Failed to load master list for chassis combo: $masterApiPath")
        }
}

/** Populate a combobox `<select>` with label row + one option per token. */
private fun populateComboboxTokensWithSeeMore(
    selectId: String,
    defaultLabel: String,
    tokens: List<String>,
    selectedValue: String,
    @Suppress("UNUSED_PARAMETER") addSeeMore: Boolean,
    preserveIfEmpty: String = "",
) {
    val select = document.getElementById(selectId) as? HTMLSelectElement ?: return
    val input = document.getElementById("${selectId}Input") as? HTMLInputElement
    select.innerHTML = ""
    val def = document.createElement("option") as HTMLOptionElement
    def.value = ""
    def.textContent = defaultLabel
    def.defaultSelected = true
    select.appendChild(def)
    val seen = mutableSetOf<String>()
    tokens.forEach { raw ->
        for (t in splitSemicolonTokens(raw)) {
            if (t.isNotBlank() && seen.add(t.lowercase())) {
                val option = document.createElement("option") as HTMLOptionElement
                option.value = t
                option.textContent = t
                select.appendChild(option)
            }
        }
    }
    val toSet = firstSemicolonToken(
        mergeChassisFieldValue(
            selectedValue.takeIf { it.isNotBlank() } ?: tokens.firstOrNull() ?: "",
            preserveIfEmpty,
        ),
    )
    if (toSet.isNotBlank()) {
        var found = false
        for (i in 0 until select.options.length) {
            val o = select.options.item(i) as? HTMLOptionElement
            if (o != null && o.value == toSet) {
                found = true
                break
            }
        }
        if (!found) {
            val opt = document.createElement("option") as HTMLOptionElement
            opt.value = toSet
            opt.textContent = toSet
            select.appendChild(opt)
        }
        select.value = toSet
        input?.value = toSet
    } else {
        val keep = preserveIfEmpty.trim()
        if (keep.isNotBlank()) {
            window.asDynamic().__preserveComboId = selectId
            window.asDynamic().__preserveComboVal = keep
            js("""
                if (typeof ensureComboboxOptionExists === 'function') {
                    ensureComboboxOptionExists(window.__preserveComboId, window.__preserveComboVal);
                }
            """)
            select.value = keep
            input?.value = keep
        } else {
            select.value = ""
            input?.value = ""
        }
    }
    syncComboboxFromSelect(selectId)
}

/** Called when user clicks "See More" in Brand dropdown. Fetches master_menu car_brands and appends them below existing options. */
fun handleBrandSeeMoreClick(selectId: String) {
    val select = document.getElementById(selectId) as? HTMLSelectElement ?: return
    val input = document.getElementById("${selectId}Input") as? HTMLInputElement
    // Case-insensitive set so we only add unique brands (TOYOTA vs Toyota = one entry)
    val existingLower = mutableSetOf<String>()
    for (i in 0 until select.options.length) {
        val opt = select.options.item(i) as? HTMLOptionElement ?: continue
        val v = (opt.value ?: "").trim()
        if (v.isNotEmpty() && v != BRAND_SEE_MORE_VALUE && v != SEE_LESS_VALUE) existingLower.add(v.lowercase())
    }
    window.fetch(apiUrl("master-menu/car_brands"))
        .then { response: dynamic ->
            if (response.ok) response.json() else throw js("Error('Failed to load car brands')")
        }
        .then { raw: dynamic ->
            val masterList = parsePurchaseMasterListArray(raw)
            var seeMoreOption: HTMLOptionElement? = null
            for (i in 0 until select.options.length) {
                val opt = select.options.item(i) as? HTMLOptionElement
                if (opt != null && opt.value == BRAND_SEE_MORE_VALUE) {
                    seeMoreOption = opt
                    break
                }
            }
            val originalCount = select.options.length - 1 // number of options before See More
            seeMoreOption?.remove()
            // Append master brands that are not already present (case-insensitive); do not re-add See More
            masterList.forEach { brandName ->
                if (brandName.isNotBlank() && !existingLower.contains(brandName.lowercase())) {
                    existingLower.add(brandName.lowercase())
                    val option = document.createElement("option") as HTMLOptionElement
                    option.value = brandName
                    option.textContent = brandName
                    select.appendChild(option)
                }
            }
            val seeLessOpt = document.createElement("option") as HTMLOptionElement
            seeLessOpt.value = SEE_LESS_VALUE
            seeLessOpt.textContent = "See Less"
            select.appendChild(seeLessOpt)
            window.asDynamic().__seeMoreOriginalCountSelectId = selectId
            window.asDynamic().__seeMoreOriginalCountValue = originalCount
            js("window.__seeMoreOriginalCount = window.__seeMoreOriginalCount || {}; window.__seeMoreOriginalCount[window.__seeMoreOriginalCountSelectId] = window.__seeMoreOriginalCountValue;")
            val inputVal = input?.value ?: ""
            window.asDynamic().__brandSeeMoreSelectId = selectId
            window.asDynamic().__brandSeeMoreInputVal = inputVal
            js("if (typeof window.filterComboboxDropdown === 'function') { window.filterComboboxDropdown(window.__brandSeeMoreSelectId, window.__brandSeeMoreInputVal); }")
            // Close and re-open dropdown so it expands correctly (fixes truncated list after See More)
            js("if (typeof window.closeComboboxDropdown === 'function') { window.closeComboboxDropdown(window.__brandSeeMoreSelectId); }")
            js("setTimeout(function() { if (typeof window.openComboboxDropdown === 'function' && window.__brandSeeMoreSelectId) { window.openComboboxDropdown(window.__brandSeeMoreSelectId); } }, 50);")
        }
        .catch { _: dynamic ->
            console.error("Failed to load master car brands for See More")
        }
}

