/** Called when user clicks "See Less". Restores dropdown to state before "See More" was clicked (removes expanded options, re-adds "See More"). */
fun handleSeeLessClick(selectId: String) {
    window.asDynamic().__seeLessSelectId = selectId
    js("""
        (function() {
            var selectId = window.__seeLessSelectId;
            var c = window.__seeMoreOriginalCount;
            if (!c || !selectId) return;
            var originalCount = c[selectId];
            if (originalCount == null) return;
            var select = document.getElementById(selectId);
            if (!select) return;
            while (select.options.length > originalCount) select.removeChild(select.options[select.options.length - 1]);
            var opt = document.createElement('option');
            opt.value = '__SEE_MORE__';
            opt.textContent = 'See More';
            select.appendChild(opt);
            delete c[selectId];
            var inputVal = (document.getElementById(selectId + 'Input') && document.getElementById(selectId + 'Input').value) || '';
            if (typeof window.filterComboboxDropdown === 'function') window.filterComboboxDropdown(selectId, inputVal);
            if (typeof window.closeComboboxDropdown === 'function') window.closeComboboxDropdown(selectId);
            setTimeout(function() { if (typeof window.openComboboxDropdown === 'function') window.openComboboxDropdown(selectId); }, 50);
        })();
    """)
}

// Function to populate dropdowns for chassis-first flow (does NOT filter chassis dropdown)
// mappingValues: values from chassis mapping - if null/empty, preserve existing form values
fun populateBrandDropdownsForChassisFlow(
    dropdowns: dynamic, 
    isEditForm: Boolean,
    carName: String? = null,
    fuel: String? = null,
    wd: String? = null,
    shift: String? = null,
    cc: String? = null,
    door: String? = null,
    grade: String? = null
) {
    // Helper function to resolve field IDs for add vs edit forms.
    fun fieldId(base: String): String {
        val id = if (isEditForm) {
            "edit$base"
        } else {
            // Explicit mapping for add form to match actual element IDs
            when (base) {
                "Chassis" -> "chassis"
                "CarName" -> "carName"
                "Fuel" -> "fuel"
                "Wd" -> "wd"
                "Cc" -> "cc"
                "Door" -> "door"
                "Grade" -> "grade"
                "Shift" -> "shift"
                else -> base.lowercase()
            }
        }
        console.log("populateBrandDropdownsForChassisFlow: resolving fieldId for", base, "->", id, "isEditForm=", isEditForm)
        return id
    }
    
    // Helper function to populate a dropdown (and sync to input if it's a combobox)
    // Preserves existing selected value if mapping doesn't have a value for this field
    fun populateDropdown(fieldId: String, values: Array<String>, defaultLabel: String, preserveValue: String? = null) {
        console.log("populateBrandDropdownsForChassisFlow: populating dropdown", fieldId, "with", values.size, "values, defaultLabel=", defaultLabel, "preserveValue=", preserveValue)
        val element = document.getElementById(fieldId) as? HTMLSelectElement
        
        if (element == null) {
            console.error("populateBrandDropdownsForChassisFlow: no select element found for", fieldId, "- skipping")
            return
        }
        
        val flatValues = flattenSemicolonChoices(values.toList())
        
        // For Fuel/Shift/Grade, merge with base options instead of clearing
        val isBaseOptionField = fieldId == "fuel" || fieldId == "editFuel" || 
                                fieldId == "shift" || fieldId == "editShift" || 
                                fieldId == "grade" || fieldId == "editGrade"
        
        if (isBaseOptionField) {
            // Merge approach: keep existing base options, add new values
            val baseOptionsMap = mapOf(
                "fuel" to listOf("GASOLINE", "DIESEL", "HYBRID", "CNG", "EV", "HYDROGEN", "PHEV"),
                "editFuel" to listOf("GASOLINE", "DIESEL", "HYBRID", "CNG", "EV", "HYDROGEN", "PHEV"),
                "shift" to listOf("AT", "MT", "6F", "5F"),
                "editShift" to listOf("AT", "MT", "6F", "5F"),
                "grade" to listOf("G", "S", "S-T", "X", "Z", "OPEN DECK", "S X VER", "S KIRAMEKI"),
                "editGrade" to listOf("G", "S", "S-T", "X", "Z", "OPEN DECK", "S X VER", "S KIRAMEKI")
            )
            
            val baseOptions = baseOptionsMap[fieldId] ?: emptyList()
            val allValuesSet = mutableSetOf<String>()
            
            // Add base options first
            baseOptions.forEach { allValuesSet.add(it) }
            // Add values from mapping (each token is its own row)
            flatValues.forEach { allValuesSet.add(it) }
            
            // Clear and rebuild with merged options
            element.innerHTML = ""
            val defaultOption = js("new Option(defaultLabel, '', true, true)")
            element.add(defaultOption)
            
            // Add all merged options (sorted for consistency)
            allValuesSet.sorted().forEach { value ->
                val option = js("new Option(value, value)")
                element.add(option)
            }
            
            console.log("✅ Merged base options for $fieldId: ${allValuesSet.size} total options (${baseOptions.size} base + mapping tokens from ${values.size} raw rows)")
        } else {
            // For other fields, clear and repopulate normally
            element.innerHTML = ""
            val defaultOption = js("new Option(defaultLabel, '', true, true)")
            element.add(defaultOption)
            
            flatValues.forEach { value ->
                if (value.isNotEmpty()) {
                    val option = js("new Option(value, value)")
                    element.add(option)
                }
            }
        }
        
        // If preserveValue is provided (mapping has a value), set it
        // If preserveValue is null (mapping is empty), leave it as default (empty)
        if (preserveValue != null && preserveValue.isNotBlank()) {
            // Check if value exists in options
            var valueExists = false
            for (i in 0 until element.options.length) {
                val option = element.options.item(i) as? HTMLOptionElement
                if (option != null && option.value == preserveValue) {
                    valueExists = true
                    break
                }
            }
            if (valueExists) {
                element.value = preserveValue
                console.log("✅ Set dropdown value from mapping for $fieldId: $preserveValue")
            } else {
                console.log("⚠️ Mapping value '$preserveValue' not found in dropdown options for $fieldId")
            }
        } else {
            // Mapping is empty - clear the field (set to default empty option)
            element.value = ""
            console.log("✅ Cleared $fieldId (mapping had no value)")
        }
        
        console.log("populateBrandDropdownsForChassisFlow: finished populating", fieldId, "- total options:", element.options.length)
    }
    
    // NOTE: Do NOT populate chassis dropdown - it should always show all chassis options
    // Only populate other dropdowns (car name, fuel, wd, etc.) based on the brand from chassis mapping
    // If mapping value is null/empty, preserve existing form value
    
    val carNameList = js("dropdowns.carName") as? Array<String> ?: emptyArray()
    populateDropdown(fieldId("CarName"), carNameList, "Select Car Name", carName)
    
    // Ensure Fuel dropdown always includes base options; split any `a;b;c` rows from API
    val baseFuelOptions = listOf("GASOLINE", "DIESEL", "HYBRID", "CNG", "EV", "HYDROGEN", "PHEV")
    val fuelList = flattenSemicolonChoices(
        baseFuelOptions + (js("dropdowns.fuel") as? Array<String> ?: emptyArray()).toList()
    )
    populateDropdown(fieldId("Fuel"), fuelList.toTypedArray(), "Select Fuel", fuel)
    
    val wdList = js("dropdowns.wd") as? Array<String> ?: emptyArray()
    populateDropdown(fieldId("Wd"), wdList, "Select WD", wd)
    
    // Ensure Shift dropdown always includes base options; split any `a;b;c` rows from API
    val baseShiftOptions = listOf("AT", "MT", "6F", "5F")
    val shiftList = flattenSemicolonChoices(
        baseShiftOptions + (js("dropdowns.shift") as? Array<String> ?: emptyArray()).toList()
    )
    populateDropdown(fieldId("Shift"), shiftList.toTypedArray(), "Select Shift", shift)
    
    val ccList = js("dropdowns.cc") as? Array<String> ?: emptyArray()
    populateDropdown(fieldId("Cc"), ccList, "Select CC", cc)
    
    val doorList = js("dropdowns.door") as? Array<String> ?: emptyArray()
    populateDropdown(fieldId("Door"), doorList, "Select Door", door)
    
    // Grade dropdown options come from master_menu/car_grade; chassis mapping only auto-fills Grade value
    
    // Ensure base options remain available after mapping population
    ensureBaseComboboxOptionsForAddEdit()
    
    console.log("✅ Populated dropdowns for chassis-first flow (chassis dropdown unchanged)")
}

