                brandInput.value = matchedBrand
            }
            js("window.__tempBrandId = brandId")
            js("if (typeof window.syncComboboxInput === 'function') { window.syncComboboxInput(window.__tempBrandId); }")
            console.log("✅ Auto-filled brand from match: $matchedBrand")
