        val fuelId = getFieldId("Fuel")
        val fuelSelect = document.getElementById(fuelId) as? HTMLSelectElement
        val fuelInput = document.getElementById("${fuelId}Input") as? HTMLInputElement
        if (fuelSelect != null) {
            fuelSelect.value = matchedFuel
            if (fuelInput != null) {
                fuelInput.value = matchedFuel
            }
            syncComboboxField("Fuel", matchedFuel)
            console.log("✅ Auto-filled fuel from match: $matchedFuel")
        }
    }
    
    // WD (2WD/4WD radios)
    if (changedField.lowercase() != "wd") {
        val normalizedWd = if (matchedWd.contains("4")) "4WD" else if (matchedWd.contains("2")) "2WD" else ""
        val wdRadioName = if (isEditForm) "editWd" else "wd"
