            if (wdRadio != null) {
                wdRadio.checked = true
                console.log("✅ Auto-filled wd from match: $normalizedWd")
            }
        }
    }
    
    // Shift
    if (changedField.lowercase() != "shift") {
        val shiftId = getFieldId("Shift")
        val shiftSelect = document.getElementById(shiftId) as? HTMLSelectElement
        val shiftInput = document.getElementById("${shiftId}Input") as? HTMLInputElement
        if (shiftSelect != null) {
            shiftSelect.value = matchedShift
            if (shiftInput != null) {
                shiftInput.value = matchedShift
            }
            console.log("✅ Auto-filled shift from match: $matchedShift")
        }
    }
    
    // CC (numeric text input on purchase forms)
    if (changedField.lowercase() != "cc") {
        val ccId = getFieldId("Cc")
        val ccInput = document.getElementById(ccId) as? HTMLInputElement
            if (ccInput != null) {
            val num = matchedCc.replace(Regex("[^0-9]"), "")
            ccInput.value = num
            console.log("✅ Auto-filled cc from match: $num")
        }
    }
    
    // Door (number input)
    if (changedField.lowercase() != "door") {
        val doorId = getFieldId("Door")
