                // If we're auto-filling, preserve autoFilledBrand
                if (isAutoFilling) {
                    if (brandName.isNotBlank()) {
                        window.asDynamic().autoFilledBrand = brandName
                        console.log("✅ Preserving autoFilledBrand during auto-fill: '$brandName'")
                    }
                } else {
                    // User manually changed brand - update autoFilledBrand for brand mapping modal
                    if (brandName.isNotBlank()) {
                        window.asDynamic().autoFilledBrand = brandName
                        console.log("✅ Updated autoFilledBrand: '$brandName'")
                        
