                        }
                    } else {
                        // Brand cleared - clear autoFilledBrand
                        js("window.autoFilledBrand = null")
                        console.log("🔄 Brand cleared - clearing autoFilledBrand")
                    }
                }
            }
            targetId == "editBrand" || targetId == "editBrandInput" -> {
                // Brand changed - update autoFilledBrand and find matching row
                val brandName = getBrandName(isEditForm = true).trim()
                val isAutoFilling = (js("window.isAutoFillingBrand") as? Boolean) ?: false
                val isAutoFillingFromMatch = (js("window.isAutoFillingFromMatch") as? Boolean) ?: false
                console.log("🔵 Brand field changed (edit): '$brandName' (isAutoFilling: $isAutoFilling, isAutoFillingFromMatch: $isAutoFillingFromMatch)")
                
                // If we're auto-filling, preserve autoFilledBrand
                if (isAutoFilling) {
