    }
}

// Helper function to find label for an input field
fun findLabelForInput(inputId: String): HTMLElement? {
    val input = document.getElementById(inputId) ?: return null
    
    // Method 1: label with for attribute
    var label = document.querySelector("label[for=\"$inputId\"]") as? HTMLElement
    if (label != null) return label
    
    // Method 2: label in parent div
    label = input.parentElement?.querySelector("label") as? HTMLElement
    if (label != null) return label
    
    // Method 3: label in grandparent div (for combobox structure)
    label = input.parentElement?.parentElement?.querySelector("label") as? HTMLElement
    if (label != null) return label
    
    // Method 4: previous sibling label
    var prevSibling = input.previousElementSibling
    while (prevSibling != null) {
        if (prevSibling.tagName == "LABEL") {
            return prevSibling as HTMLElement
        }
        prevSibling = prevSibling.previousElementSibling
    }
    
    return null
}

