/** Normalize carPictures (DB string, JSON array, or null) to a stable JSON string for diffing. */
private fun normalizedCarPicturesJson(v: dynamic): String {
    val arr: dynamic = try {
        when {
            v == null || v == js("undefined") -> js("[]")
            v is String -> {
                val s = v.trim()
                if (s.isEmpty()) js("[]") else JSON.parse<dynamic>(s)
            }
            js("Array.isArray(v)").unsafeCast<Boolean>() -> v
            else -> js("[]")
        }
    } catch (_: Throwable) {
        js("[]")
    }
    val n = js("arr.length").unsafeCast<Int>()
    val items = mutableListOf<Pair<String, String>>()
    for (i in 0 until n) {
        val item = js("arr[i]")
        if (item == null || item == js("undefined")) continue
        val id = js("String(item.id !== undefined && item.id !== null ? item.id : '')").toString()
        val data = js("String(item.data !== undefined && item.data !== null ? item.data : '')").toString()
        items.add(Pair(id, data))
    }
    items.sortBy { it.first }
    val out = js("[]").unsafeCast<dynamic>()
    for ((id, data) in items) {
        val o = js("{}")
        o.id = id
        o.data = data
        out.push(o)
    }
    return JSON.stringify(out)
}

private fun carPictureCountFromNormalizedJson(json: String): Int {
    return try {
        val a = JSON.parse<dynamic>(json)
        js("a.length").unsafeCast<Int>()
    } catch (_: Throwable) {
        0
    }
}

// Function to compare original and current data and return changes
fun comparePurchaseDataChanges(original: dynamic, current: dynamic): Map<String, Pair<String, String>> {
    val changes = mutableMapOf<String, Pair<String, String>>()
    
    console.log("🔍 [COMPARE] Starting comparison...")
    console.log("🔍 [COMPARE] Original data:", JSON.stringify(original))
    console.log("🔍 [COMPARE] Current data:", JSON.stringify(current))
    
    val fieldsToCompare = listOf(
        "date", "chassis", "carModelYear", "manufactureYear", "brand", "carName", "vehicleType", "shipmentSize",
        "grade", "rank", "color", "fuel", "seat", "door", "distance", "options", "cc",
        "shift", "wd", "driveType", "auctionNo", "auctionHouse", "stockLocation", "pol",
        "rixoCompany", "clientName", "country", "venueId", "price", "auctionFee", "auctionPenaltyFee", "recycleFee",
        "roadTax", "taxTotal", "totalPrice", "paymentDate", "rixoRequested", "rixoConfirmed",
        "rixoPrice", "shipmentDate", "blNo", "vessel", "destination", "shipmentCharges",
        "freight", "storageCharges", "miscCharges", "inspectionFee", "commission", "repairCompany",
        "repairCharges", "shaken", "negotiate", "local", "numberCut", "notes", "bookingId", "bookingRequested", "sold", "invoiceConfirmed", "carPictures"
    )

    // Compare money values by numeric content only (ignore `¥`, commas, formatting, etc.)
    fun normalizeMoneyForCompare(v: dynamic): String {
        if (v == null || v == js("undefined")) return ""
        if (v is Boolean) return v.toString()
        val s = v.toString().trim()
        if (s.isEmpty()) return ""

        // Keep digits and dot only
        var cleaned = s.replace(Regex("[^0-9.]"), "")
        if (cleaned.isEmpty()) return ""

        // Collapse multiple dots (keep first dot)
        val parts = cleaned.split(".")
        cleaned = if (parts.size <= 1) parts[0] else parts[0] + "." + parts.drop(1).joinToString("")
        return cleaned
    }

    val moneyFields = setOf(
        "price",
        "auctionFee",
        "auctionPenaltyFee",
        "recycleFee",
        "roadTax",
        "taxTotal",
        "totalPrice",
        "rixoPrice",
        "shipmentCharges",
        "freight",
        "storageCharges",
        "miscCharges",
        "inspectionFee",
        "commission",
        "repairCharges"
    )

    val boolFields = setOf(
        "shaken",
        "negotiate",
        "invoiceConfirmed",
        "local",
        "bookingRequested",
        "sold",
    )

    fun normalizeBoolForCompare(v: dynamic): String {
        if (v == null || v == js("undefined")) return "false"
        if (v is Boolean) return if (v) "true" else "false"
        val s = v.toString().trim().lowercase()
        return when {
            s.isEmpty() -> "false"
            s == "true" || s == "1" || s == "yes" -> "true"
            else -> "false"
        }
    }
    
    Logger.debug("[COMPARE] Comparing ${fieldsToCompare.size} fields...")
    
    fieldsToCompare.forEach { fieldName ->
        // Use JavaScript bracket notation to safely access dynamic object properties
        val originalValue = try {
            if (original != null) {
                js("original[fieldName]")
            } else null
        } catch (e: dynamic) {
            null
        }
        val currentValue = try {
            if (current != null) {
                js("current[fieldName]")
            } else null
        } catch (e: dynamic) {
            null
        }
        
        if (fieldName == "carPictures") {
            val origRaw = carPicturesFieldFromPurchase(original) ?: originalValue
            val origJson = normalizedCarPicturesJson(origRaw)
            val currJson = normalizedCarPicturesJson(currentValue)
            if (origJson != currJson) {
                val oc = carPictureCountFromNormalizedJson(origJson)
                val cc = carPictureCountFromNormalizedJson(currJson)
                changes[fieldName] = Pair(
                    if (oc == 0) "(no pictures)" else "$oc picture(s)",
                    if (cc == 0) "(no pictures)" else "$cc picture(s)"
                )
                console.log("[COMPARE] Change detected in carPictures: $oc → $cc")
            }
            return@forEach
        }
        
        // Normalize values for comparison (treat empty string and null as same)
        val origNormalized = when {
            fieldName == "carModelYear" -> normalizeCarModelYearForCompare(
                if (originalValue == null || originalValue == js("undefined")) "" else originalValue.toString()
            )
            fieldName in moneyFields -> normalizeMoneyForCompare(originalValue)
            fieldName in boolFields -> normalizeBoolForCompare(originalValue)
            originalValue == null || originalValue == js("undefined") -> ""
            originalValue is Boolean -> originalValue.toString()
            else -> originalValue.toString().trim()
        }
        val currNormalized = when {
            fieldName == "carModelYear" -> normalizeCarModelYearForCompare(
                if (currentValue == null || currentValue == js("undefined")) "" else currentValue.toString()
            )
            fieldName in moneyFields -> normalizeMoneyForCompare(currentValue)
            fieldName in boolFields -> normalizeBoolForCompare(currentValue)
            currentValue == null || currentValue == js("undefined") -> ""
            currentValue is Boolean -> currentValue.toString()
            else -> currentValue.toString().trim()
        }
        
        // Always log carModelYear for debugging
        if (fieldName == "carModelYear") {
            Logger.debug("[COMPARE] Field $fieldName: orig='$origNormalized' (raw: $originalValue, type: ${js("typeof originalValue")}), curr='$currNormalized' (raw: $currentValue, type: ${js("typeof currentValue")}), match=${origNormalized == currNormalized}")
        }
        
        // Debug log for fields that differ
        if (origNormalized != currNormalized) {
            Logger.debug("[COMPARE] Field $fieldName DIFFERS: orig='$origNormalized' (raw: $originalValue), curr='$currNormalized' (raw: $currentValue)")
        }
        
        // Compare normalized values
        if (origNormalized != currNormalized) {
            console.log("✅ [COMPARE] Change detected in $fieldName: '$origNormalized' → '$currNormalized'")
            changes[fieldName] = Pair(
                formatValueForDisplay(originalValue),
                formatValueForDisplay(currentValue)
            )
        }
    }
    
    console.log("🔍 [COMPARE] Total changes detected: ${changes.size}")
    return changes
}

// Function to create confirmation modal HTML
fun createEditConfirmationModal(changes: Map<String, Pair<String, String>>): String {
