// Function to show confirmation modal
fun showEditConfirmationModal(changes: Map<String, Pair<String, String>>, purchaseId: Long) {
    // Remove existing modal if any
    document.getElementById("editConfirmationModal")?.remove()
    
    // Store purchaseId in a local variable for closure capture
    val id = purchaseId
    
    // Create and insert modal
    val modalHTML = createEditConfirmationModal(changes)
    val tempDiv = document.createElement("div")
    tempDiv.innerHTML = modalHTML
    val modalElement = tempDiv.firstElementChild
    if (modalElement == null || modalElement !is HTMLElement) {
        console.error("Failed to create confirmation modal")
        return
    }
    val modal = modalElement as HTMLElement
    val body = document.body
    if (body != null) {
        body.appendChild(modal)
    }

    setRixoAutoSelectSuppress()
    
    // Close button handler
    document.getElementById("closeEditConfirmationModal")?.addEventListener("click", { _: Event ->
        document.getElementById("editConfirmationModal")?.remove()
        pendingEditAuditChangedFields = null
        clearRixoAutoSelectSuppress()
    })
    
    // Cancel button handler
    document.getElementById("cancelEditConfirmation")?.addEventListener("click", { _: Event ->
        document.getElementById("editConfirmationModal")?.remove()
        pendingEditAuditChangedFields = null
        clearRixoAutoSelectSuppress()
    })
    
    // Backdrop click handler
    modal.addEventListener("click", { event: Event ->
        if ((event.target as? HTMLElement)?.id == "editConfirmationModal") {
            document.getElementById("editConfirmationModal")?.remove()
            pendingEditAuditChangedFields = null
            clearRixoAutoSelectSuppress()
        }
    })
    
    // OK button handler
    val confirmBtn = document.getElementById("confirmEditUpdate")
    confirmBtn?.addEventListener("click", { _: Event ->
        document.getElementById("editConfirmationModal")?.remove()
        // Get chassis value for proceedWithEditPurchase
        val chassis = getComboboxValueSafe("editChassis")
        // Proceed with update
        proceedWithEditPurchase(id, chassis)
    })
}

fun handleEditPurchase() {
    console.log("🔄 handleEditPurchase() called")
    
    // Verify required window functions exist
    if (js("typeof window.getComboboxValue") != "function") {
        console.error("❌ window.getComboboxValue is not a function!")
        showErrorModal("System Error", "Required function getComboboxValue is not available. Please refresh the page.")
        return
    }
    
    // Get purchase ID with error handling
    val editIdElement = document.getElementById("editId") as? HTMLInputElement
    if (editIdElement == null) {
        console.error("❌ editId element not found!")
        showErrorModal("Error", "Purchase ID field not found. Please refresh the page.")
        return
    }
    
    val idString = editIdElement.value.trim()
    if (idString.isEmpty()) {
        console.error("❌ Purchase ID is empty!")
        showErrorModal("Error", "Purchase ID is missing. Please refresh the page.")
        return
    }
    
    val id = idString.toLongOrNull()
    if (id == null) {
        console.error("❌ Invalid Purchase ID: '$idString'")
        showErrorModal("Error", "Invalid Purchase ID: $idString. Please refresh the page.")
        return
    }
    
    console.log("✅ Purchase ID: $id")
    
    // Get all field values
    val chassis = getComboboxValueSafe("editChassis")
    val brand = getComboboxValueSafe("editBrand")
    val carName = getComboboxValueSafe("editCarName")
    val grade = getComboboxValueSafe("editGrade")
    val fuel = getComboboxValueSafe("editFuel")
    val door = getComboboxValueSafe("editDoor")
    val shift = getComboboxValueSafe("editShift")
    val wdRadio = document.querySelector("input[name=\"editWd\"]:checked") as? HTMLInputElement
    val wd = wdRadio?.value ?: ""
    val cc = getComboboxValueSafe("editCc")
    val auctionName = getComboboxValueSafe("editAuctionName")
    val stockLocation = getComboboxValueSafe("editStockLocation")
    val pol = getComboboxValueSafe("editPol")
    val venueId = getComboboxValueSafe("editVenueId")
    val rixoCompany = persistableRixoCompanyFromCombobox(getComboboxValueSafe("editRixoCompany"))
    val vehicleType = getComboboxValueSafe("editTypeOfVehicle")
    
    // Check if at least one field is filled
    val hasAtLeastOneField = listOf(
        chassis, brand, carName, grade, fuel, door, shift, wd, cc,
        auctionName, stockLocation, venueId, rixoCompany, vehicleType
    ).any { it.isNotBlank() }
    
    if (!hasAtLeastOneField) {
        showErrorModal("Validation Error", "Please fill at least one field before saving.")
        return
    }
    
    // Purchase Date: strict MM/DD/YYYY only (no loose parsing).
    val editDateEl = document.getElementById("editDate") as? HTMLInputElement
    val rawPurchaseDate = editDateEl?.value?.trim() ?: ""
    val editPurchaseDateIso = strictMmDdYyyySlashToIso(rawPurchaseDate)
    if (rawPurchaseDate.isNotBlank() && editPurchaseDateIso == null) {
        showErrorModal(
            "Invalid Purchase Date",
            "Use MM/DD/YYYY with a 2-digit month (01–12), 2-digit day (valid for that month), and 4-digit year.",
        )
        return
    }
    if (editPurchaseDateIso != null) {
        editDateEl?.value = isoToMmDdYyyy(editPurchaseDateIso)
        (document.getElementById("editDatePicker") as? HTMLInputElement)?.value = editPurchaseDateIso
    }

    // Payment Date: strict MM/DD/YYYY when non-empty.
    val editPaymentDateEl = document.getElementById("editPaymentDate") as? HTMLInputElement
    val rawPaymentDate = editPaymentDateEl?.value?.trim() ?: ""
    val editPaymentDateIso = strictMmDdYyyySlashToIso(rawPaymentDate)
    if (rawPaymentDate.isNotBlank() && editPaymentDateIso == null) {
        showErrorModal(
            "Invalid Payment Date",
            "Use MM/DD/YYYY with a 2-digit month (01–12), 2-digit day (valid for that month), and 4-digit year.",
        )
        return
    }
    if (editPaymentDateIso != null) {
        editPaymentDateEl?.value = isoToMmDdYyyy(editPaymentDateIso)
        (document.getElementById("editPaymentDatePicker") as? HTMLInputElement)?.value = editPaymentDateIso
    }

    // Shipment Date: strict MM/DD/YYYY when non-empty.
    val editShipmentDateEl = document.getElementById("editShipmentDate") as? HTMLInputElement
    val rawShipmentDate = editShipmentDateEl?.value?.trim() ?: ""
    val editShipmentDateIso = strictMmDdYyyySlashToIso(rawShipmentDate)
    if (rawShipmentDate.isNotBlank() && editShipmentDateIso == null) {
        showErrorModal(
            "Invalid Shipment Date",
            "Use MM/DD/YYYY with a 2-digit month (01–12), 2-digit day (valid for that month), and 4-digit year.",
        )
        return
    }
    if (editShipmentDateIso != null) {
        editShipmentDateEl?.value = isoToMmDdYyyy(editShipmentDateIso)
        (document.getElementById("editShipmentDatePicker") as? HTMLInputElement)?.value = editShipmentDateIso
    }
    
    // Validate Registration Date (commit typed MM/YYYY before read/compare)
    val (isValidYear, yearErrorMsg) = validateCarModelYearField("editCarModelYear")
    if (!isValidYear) {
        showErrorModal("Invalid Registration Date", yearErrorMsg)
        return
    }

    val editManufactureYear = readManufactureYearInput("editManufactureYear")
    val (isValidManufactureYear, manufactureYearErrorMsg) = validateManufactureYear(editManufactureYear)
    if (!isValidManufactureYear) {
        showErrorModal("Invalid Manufacture Year", manufactureYearErrorMsg)
        return
    }

    if (!validateNumberCutWhenShaken(isEdit = true)) {
        return
    }
    
    // NOTE:
    // There used to be a brittle "direct DOM dropdown validation" here that blocks saving if a select
    // element temporarily doesn't contain the current input value (common during async dropdown loading).
    // This caused the repeated error message you reported. We skip this DOM-level blocking validation and
    // rely on the existing master-menu validation + backend checks instead.
    
    // Validate chassis Part 1 is from dropdown (two-part chassis logic)
    if (chassis.isNotBlank() && !validateChassisPart1(chassis, isEditForm = true)) {
        showErrorModal("Invalid Chassis", "Please select chassis from dropdown. The first part cannot be edited manually.")
        return
    }

    checkPurchaseDuplicate(
        chassis = chassis,
        excludeId = id,
        onDuplicate = { msg -> showErrorModal("Duplicate Purchase", msg) },
        onOk = { continueEditPurchaseAfterDuplicateCheck(id, chassis) },
    )
}

private fun continueEditPurchaseAfterDuplicateCheck(id: Long, chassis: String) {
    
    // Collect current form data
    val currentData = collectCurrentEditFormData()
    console.log("🔍 [COMPARE] Collected current form data")
    
    // Compare with original data
    if (originalPurchaseData != null) {
        console.log("🔍 [COMPARE] Original purchase data available, comparing...")
        val changes = comparePurchaseDataChanges(originalPurchaseData, currentData)
        
        if (changes.isEmpty()) {
            // No changes detected
            console.log("⚠️ [COMPARE] No changes detected - showing info message")
            showMessage("No changes detected. Nothing to update.", "info")
            return
        }
        
        // Show confirmation modal with changes
        console.log("📋 Showing confirmation modal with ${changes.size} change(s)")
        pendingEditAuditChangedFields = changes.keys.toTypedArray()
        showEditConfirmationModal(changes, id)
    } else {
        // Original data not available, proceed directly (fallback)
        console.log("⚠️ Original purchase data not available, proceeding without confirmation")
        proceedWithEditPurchase(id, chassis)
    }
}

