// Submit edit purchase request
fun submitEditPurchase(id: Long, purchaseData: dynamic) {
    // Call API to update purchase
    val requestInit = js("{}")
    requestInit.method = "PUT"
    val headers = js("{}")
    headers["Content-Type"] = "application/json"
    requestInit.headers = headers
    requestInit.body = JSON.stringify(purchaseData)
    
    // Debug: Log the actual JSON being sent, especially shaken field and bookingId
    val parsedBody = JSON.parse<dynamic>(requestInit.body)
    console.log("🔍 [DEBUG] Edit Purchase - Request body JSON:", requestInit.body)
    console.log("🔍 [DEBUG] Edit Purchase - Shaken in JSON:", parsedBody.shaken, "Type:", js("typeof parsedBody.shaken"))
    console.log("🔍 [DEBUG] Edit Purchase - BookingId in JSON:", parsedBody.bookingId, "Type:", js("typeof parsedBody.bookingId"))
    console.log("Request headers:", headers)
    console.log("Request body:", requestInit.body)
    
    window.fetch(apiUrl("purchases/$id"), requestInit).then { response ->
        if (response.ok) {
            response.json().then { updatedPurchase: dynamic ->
                refreshEditPurchaseAfterSuccessfulSave(id, updatedPurchase)
                pendingEditAuditChangedFields = null
                showMessage("Purchase updated successfully!", "success")
                clearRixoAutoSelectSuppress()
            }.catch { err: dynamic ->
                console.warn("Edit save OK but response parse failed:", err)
                refreshEditPurchaseAfterSuccessfulSave(id, null)
                pendingEditAuditChangedFields = null
                showMessage("Purchase updated successfully!", "success")
                clearRixoAutoSelectSuppress()
            }
        } else {
            pendingEditAuditChangedFields = null
            response.text().then { errorText ->
                console.log("Update error response: $errorText")
                // Try to parse as JSON first
                try {
                    val errorJson = JSON.parse<dynamic>(errorText)
                    val errorMessage = errorJson.message as? String ?: errorText
                    
                    if (isPurchaseDuplicateError(response.status, errorMessage)) {
                        showErrorModal("Duplicate Purchase", errorMessage)
                    } else {
                        showMessage("Failed to update purchase: $errorMessage", "error")
                    }
                } catch (e: dynamic) {
                    // If JSON parsing fails, check the raw text
                    if (isPurchaseDuplicateError(response.status, errorText)) {
                        showErrorModal("Duplicate Purchase", errorText)
                    } else {
                showMessage("Failed to update purchase: $errorText", "error")
                    }
                }
                clearRixoAutoSelectSuppress()
            }.catch { _: Throwable ->
                clearRixoAutoSelectSuppress()
            }
        }
        undefined
    }.catch { error ->
        console.log("Update error: ${error.message}")
        showMessage("Failed to update purchase: ${error.message}", "error")
        clearRixoAutoSelectSuppress()
    }
}

// Collect car pictures data for saving
fun collectCarPictures(): dynamic {
    val pictures = js("[]")
    
    val containerIds = listOf("carPicturePreview", "existingPicturesList")
    for (containerId in containerIds) {
        val previewDiv = document.getElementById(containerId)
    if (previewDiv != null) {
        val pictureElements = previewDiv.querySelectorAll("div[data-picture-id]")
        for (i in 0 until pictureElements.length) {
            val element = pictureElements.item(i) as HTMLElement
            val pictureId = element.getAttribute("data-picture-id")
            val pictureData = element.getAttribute("data-picture-data")
            if (pictureId != null && pictureData != null) {
                val pictureObj = js("{}")
                pictureObj.id = pictureId
                pictureObj.data = pictureData
                pictures.push(pictureObj)
                }
            }
        }
    }
    
    console.log("📷 Collected ${pictures.length} car pictures")
    return pictures
}

