fun sortPurchasesByDate(sortOrder: String) {
    Logger.debug("Sorting purchases by date: $sortOrder")
    
    minimalPurchaseScope.launch {
        val result = ApiClient.get<Array<PurchaseResponse>>("purchases")
        result.fold(
            onSuccess = { purchases ->
                val sortedPurchases = purchases.sortedWith { a, b ->
                    val dateA = parseDateForSorting(a.date ?: "")
                    val dateB = parseDateForSorting(b.date ?: "")
                    
                    when (sortOrder) {
                        "asc" -> when {
                            dateA == null && dateB == null -> 0
                            dateA == null -> 1
                            dateB == null -> -1
                            else -> dateA.compareTo(dateB)
                        }
                        "desc" -> when {
                            dateA == null && dateB == null -> 0
                            dateA == null -> 1
                            dateB == null -> -1
                            else -> dateB.compareTo(dateA)
                        }
                        else -> 0
                    }
                }
                
                allPurchases = sortedPurchases.map { it.asDynamic() }.toTypedArray()
                displayPurchasesWithPagination()
                showMessage("Purchases sorted by date ($sortOrder)", "success")
            },
            onError = { message, _ ->
                ErrorHandler.showError("Failed to load purchases for sorting: $message")
            }
        )
    }
}

