fun applyDateFilter(selectedDate: String) {
    // Convert the selected date to the format used in the database
    val formattedDate = formatDateForDatabase(selectedDate)
    Logger.debug("Filtering by date: $formattedDate")
    
    minimalPurchaseScope.launch {
        val result = ApiClient.get<Array<PurchaseResponse>>("purchases")
        result.fold(
            onSuccess = { purchases ->
                val filteredPurchases = purchases.filter { purchase ->
                    val purchaseDate = purchase.date ?: ""
                    val isMatch = purchaseDate == formattedDate || 
                                 purchaseDate == formattedDate.split("(")[0].trim() ||
                                 normalizeDateForComparison(purchaseDate) == normalizeDateForComparison(formattedDate)
                    
                    if (isMatch) {
                        Logger.debug("Date match for chassis ${purchase.chassis ?: ""} on $purchaseDate")
                    }
                    isMatch
                }
                
                allPurchases = filteredPurchases.map { it.asDynamic() }.toTypedArray()
                displayPurchasesWithPagination()
                
                // Hide the date filter menu
                val allMenus = document.querySelectorAll(".date-filter-menu")
                for (j in 0 until allMenus.length) {
                    val menuItem = allMenus.item(j) as? HTMLElement
                    menuItem?.style?.setProperty("display", "none", "important")
                    menuItem?.style?.setProperty("pointer-events", "none")
                }
                
                showMessage("Showing purchases for $formattedDate", "success")
            },
            onError = { message, _ ->
                ErrorHandler.showError("Failed to load purchases for filtering: $message")
            }
        )
    }
}

