// Fetch purchases based on CLIENT (consignee) and VESSEL
fun fetchInvoicePurchases(consignee: String, vessel: String) {
    if (consignee.isEmpty() || vessel.isEmpty()) {
        // Clear table if either field is empty
        val tableBody = document.getElementById("invoiceListTableBody")
        if (tableBody != null) {
            tableBody.innerHTML = ""
        }
        val totalElement = document.getElementById("invoiceTotalAmount")
        if (totalElement != null) {
            totalElement.textContent = "TOTAL AMOUNT: ¥000,000"
        }
        js("window.currentInvoicePurchaseIds = []")
        return
    }
    
    window.fetch(apiUrl("purchases"))
        .then { response: dynamic ->
            if (response.ok) response.json() else throw js("Error('Failed to load purchases')")
        }
        .then { purchases: dynamic ->
            val purchasesArray = js("Array.isArray(purchases) ? purchases : []") as Array<dynamic>
            
            // Filter purchases matching consignee and vessel (case-insensitive)
            val matchingPurchases = mutableListOf<dynamic>()
            for (purchase in purchasesArray) {
                val purchaseConsignee = js("purchase.consignee")?.toString()?.trim() ?: ""
                val purchaseVessel = js("purchase.vessel")?.toString()?.trim() ?: ""
                
                if (purchaseConsignee.equals(consignee, ignoreCase = true) && 
                    purchaseVessel.equals(vessel, ignoreCase = true)) {
                    matchingPurchases.add(purchase)
                }
            }
            
            if (matchingPurchases.isEmpty()) {
                showMessage("No purchases found for selected CLIENT and VESSEL", "warning")
                // Clear table
                val tableBody = document.getElementById("invoiceListTableBody")
                if (tableBody != null) {
                    tableBody.innerHTML = ""
                }
                val totalElement = document.getElementById("invoiceTotalAmount")
                if (totalElement != null) {
                    totalElement.textContent = "TOTAL AMOUNT: ¥000,000"
                }
                js("window.currentInvoicePurchaseIds = []")
                return@then
            }
            
            // Auto-fill form fields from first matching purchase
            val firstPurchase = matchingPurchases.firstOrNull() ?: return@then
            val shipmentDate = js("firstPurchase.shipmentDate")?.toString()?.trim() ?: ""
            val stockLocation = js("firstPurchase.stockLocation")?.toString()?.trim() ?: ""
            val destination = js("firstPurchase.destination")?.toString()?.trim() ?: ""
            
            // Populate SHIPPING DATE
            val shippingDateInput = document.getElementById("invoiceShippingDate") as? HTMLInputElement
            if (shippingDateInput != null && shipmentDate.isNotEmpty()) {
                val formattedDate = when {
                    shipmentDate.contains("T") -> {
                        val datePart = shipmentDate.substring(0, 10)
                        if (datePart.matches(Regex("\\d{4}-\\d{2}-\\d{2}"))) datePart else ""
                    }
                    shipmentDate.matches(Regex("\\d{4}-\\d{2}-\\d{2}")) -> shipmentDate
                    else -> {
                        try {
                            val dateObj = js("new Date(shipmentDate)")
                            val dateDynamic = dateObj.asDynamic()
                            val year = dateDynamic.getFullYear() as? Int ?: 0
                            val month = (dateDynamic.getMonth() as? Int ?: 0) + 1
                            val day = dateDynamic.getDate() as? Int ?: 0
                            if (year > 0 && month > 0 && day > 0) {
                                "${year}-${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}"
    } else {
                                ""
                            }
                        } catch (e: dynamic) {
                            ""
                        }
                    }
                }
                if (formattedDate.isNotEmpty()) {
                    shippingDateInput.value = formattedDate
                }
            }
            
            // Populate FROM
            val fromInput = document.getElementById("invoiceFrom") as? HTMLInputElement
            if (fromInput != null) {
                fromInput.value = stockLocation
            }
            
            // Populate TO
            val toInput = document.getElementById("invoiceTo") as? HTMLInputElement
            if (toInput != null) {
                toInput.value = destination
            }
            
            // Populate LIST table
            populateInvoiceListTableFromPurchases(matchingPurchases)
        }
        .catch { error: dynamic ->
            console.error("Error fetching invoice purchases:", error)
            showMessage("Error fetching purchases", "error")
        }
}

// Populate invoice LIST table from purchase objects
fun populateInvoiceListTableFromPurchases(purchases: List<dynamic>) {
    val tableBody = document.getElementById("invoiceListTableBody") ?: return
    
    // Store purchase IDs for PDF and Ship Cars functions
    val purchaseIds = mutableListOf<Long>()
    
    // Clear table body
    tableBody.innerHTML = ""
    
    var totalAmount = 0.0
    var rowNumber = 1
    
    // Populate table rows
    for (purchase in purchases) {
        val id = js("purchase.id")?.toString()?.toLongOrNull()
        if (id != null) {
            purchaseIds.add(id)
        }
        
        val chassis = js("purchase.chassis")?.toString() ?: "N/A"
        val carName = js("purchase.carName")?.toString() ?: "N/A"
        val year = js("purchase.carModelYear")?.toString() ?: "N/A"
        
        val amount = purchaseInvoiceLineAmountYenFromDynamic(purchase)
        totalAmount += amount
        
        val amountInt = amount.toInt()
        val amountStr = amountInt.toString()
        val reversed = amountStr.reversed()
        val chunked = reversed.chunked(3)
        val joined = chunked.joinToString(",")
        val finalReversed = joined.reversed()
        val formattedAmount = "¥$finalReversed"
        
        val row = document.createElement("tr")
        row.innerHTML = """
            <td>$rowNumber</td>
            <td>$chassis</td>
            <td>$carName</td>
            <td>$year</td>
            <td>$formattedAmount</td>
        """
        tableBody.appendChild(row)
        rowNumber++
    }
    
    // Update total amount
    val totalElement = document.getElementById("invoiceTotalAmount")
    val totalInt = totalAmount.toInt()
    val totalStr = totalInt.toString()
    val totalReversed = totalStr.reversed()
    val totalChunked = totalReversed.chunked(3)
    val totalJoined = totalChunked.joinToString(",")
    val totalFinalReversed = totalJoined.reversed()
    val formattedTotal = "¥$totalFinalReversed"
    totalElement?.textContent = "TOTAL AMOUNT: $formattedTotal"
    
    // Store purchase IDs in JavaScript variable
    val idsArray = js("[]")
    purchaseIds.forEach { id ->
        js("idsArray.push(id)")
    }
    js("window.currentInvoicePurchaseIds = idsArray")
}

