// Helper function to escape JSON strings
fun escapeJsonString(str: String): String {
    // Comprehensive JSON escaping including Unicode and control characters
    return str.replace("\\", "\\\\")
        .replace("\"", "\\\"")
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t")
        .replace("\b", "\\b")
        .replace("\u000C", "\\f") // Form feed
        // Escape control characters (0x00-0x1F) except already handled ones
        .replace(Regex("[\u0000-\u0008\u000B\u000E-\u001F]")) { match ->
            val code = match.value[0].code
            "\\u${code.toString(16).padStart(4, '0').uppercase()}"
        }
}

