private fun purchaseIsBookingRequested(purchase: dynamic): Boolean {
    val v: dynamic = js("purchase.bookingRequested")
    if (v == true) return true
    if (v is Number) return v.toInt() != 0
    val s = v?.toString()?.trim()?.lowercase() ?: ""
    return s == "true" || s == "1"
