// Check if full chassis already exists on another purchase
fun checkPurchaseDuplicate(
    chassis: String,
    excludeId: Long? = null,
    onDuplicate: (message: String) -> Unit,
    onOk: () -> Unit,
) {
    val c = chassis.trim()
    if (c.isEmpty()) {
        onOk()
        return
    }

    val encChassis = js("encodeURIComponent")(c) as String
    var url = "purchases/check-duplicate?chassis=$encChassis"
    if (excludeId != null) {
        url += "&excludeId=$excludeId"
    }

    console.log("🔍 Checking duplicate chassis:", c, "excludeId:", excludeId)
    window.fetch(apiUrl(url)).then { response ->
        if (response.ok) {
            response.json().then { data ->
                val isDuplicate = js("data && data.duplicate === true").unsafeCast<Boolean>()
                if (isDuplicate) {
                    val msg = js("data && data.message ? String(data.message) : ''").toString().ifBlank {
                        "Update failed! Chassis already exists in another purchase."
                    }
                    console.warn("⚠️ Duplicate purchase:", msg)
                    onDuplicate(msg)
                } else {
                    onOk()
                }
            }.catch { error ->
                console.warn("⚠️ Could not parse duplicate check response, proceeding:", error)
                onOk()
            }
        } else {
            console.warn("⚠️ Duplicate check request failed (${response.status}), proceeding")
            onOk()
        }
    }.catch { error ->
        console.warn("⚠️ Could not check purchase duplicate, proceeding anyway:", error)
        onOk()
    }
}

private fun isPurchaseDuplicateError(status: dynamic, message: String): Boolean {
    val statusCode = (status as? Number)?.toInt() ?: 0
    val lower = message.lowercase()
    return statusCode == 409 ||
        lower.contains("already exists") ||
        lower.contains("update failed!") ||
        lower.contains("duplicate found")
}

// Legacy chassis-only check (superseded by checkPurchaseDuplicate)
fun checkChassisExists(chassis: String, excludeId: Long? = null, onExists: () -> Unit, onNotExists: () -> Unit) {
    if (chassis.isBlank()) {
        onNotExists()
        return
    }
    
    // Use the costs-by-chassis endpoint to check if chassis exists
    console.log("🔍 Checking chassis existence: '$chassis', excludeId: $excludeId")
    window.fetch(apiUrl("purchases/costs-by-chassis/$chassis")).then { response ->
            if (response.ok) {
            response.json().then { data ->
                console.log("🔍 Chassis check response data:", data)
                val purchaseId = js("data.id")?.toString()?.toLongOrNull()
                console.log("🔍 Extracted purchaseId:", purchaseId, "excludeId:", excludeId)
                
                // If excludeId is provided (edit mode), check if it's a different purchase
                if (excludeId != null && purchaseId == excludeId) {
                    // Same purchase, chassis is not duplicate
                    console.log("✅ Same purchase, no duplicate")
                    onNotExists()
                } else if (purchaseId != null) {
                    // Chassis exists and it's a different purchase (or no excludeId in add mode)
                    console.log("⚠️ Chassis exists for different purchase (ID: $purchaseId)")
                    onExists()
            } else {
                    // Chassis doesn't exist (no ID in response)
                    console.log("✅ Chassis doesn't exist (no ID in response)")
                    onNotExists()
            }
        }.catch { error ->
                // If parsing fails, assume chassis doesn't exist
                console.warn("⚠️ Error parsing chassis check response:", error)
                onNotExists()
            }
        } else {
            // If 404 or other error, chassis doesn't exist
            console.log("✅ Chassis doesn't exist (response not OK: ${response.status})")
            onNotExists()
        }
    }.catch { error ->
        // On network error, proceed anyway (let backend handle validation)
        console.warn("⚠️ Could not check chassis existence, proceeding anyway:", error)
        onNotExists()
    }
}

