    val insurance = (document.getElementById("insurance") as HTMLInputElement).value.toDoubleOrNull() ?: 0.0
    
    val baseTotal = containerPrice + shippingCharge + wcCharge + inspectionFee + fobPrice + freightPrice + insurance
